import React from "react";
import { totalDivClass } from "../../../lib/constants/classes";
import { Chart, ArcElement, Tooltip, Legend } from "chart.js";
import { Doughnut } from "react-chartjs-2";
import { AiFillEye } from "react-icons/ai";
import { BsArrowRight } from "react-icons/bs";

Chart.register(ArcElement, Tooltip, Legend);

const PieComp = () => {
	return (
		<div className={totalDivClass}>
			<div>
				<PieGraph />
			</div>
			<div className="flex flex-col items-center justify-between gap-y-0">
				<p className="text-sidebar text-title font-bold">Active Viewers</p>
				<div className="flex items-center justify-between gap-x-3">
					<AiFillEye size={20} color="#000" />
					<p className="text-[22px] text-[#37A945] font-bold">14067</p>
				</div>
				<div className="flex items-center gap-x-1 cursor-pointer">
					<p className="text-sidebar text-[12px] font-medium underline">View Detailed Analytics</p>
					<BsArrowRight size={12} color="#004B95" />
				</div>
			</div>
		</div>
	);
};

export default PieComp;

const PieGraph = () => {
	const data = {
		datasets: [
			{
				data: [40, 60],
				backgroundColor: ["#34B3F1", "#292D30"],
				// borderColor: ["#34B3F1", "#292D30"],
				hoverOffset: 4,
				rotation: -95,
			},
		],
	};
	return (
		<div>
			<Doughnut data={data} className="w-28 h-28" />
		</div>
	);
};
