import React from "react";
import { BsArrowRightShort } from "react-icons/bs";

//Styles for text editor logic
import "../css/froala_editor.css";

function Job1() {
	const javaScripts = ["https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/codemirror.min.js", "https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/mode/xml/xml.min.js", "/static/js/froala_editor.min.js", "/static/js/output.min.js", "/static/js/editorLoader.js"];

	for (let i = 0; i < javaScripts.length; i++) {
		let element = javaScripts[i];
		let script = document.createElement("script");
		script.src = element;
		script.type = "text/javascript";
		document.body.appendChild(script);
	}

	return (
		<>
			<div className="  flex justify-between">
				<div className="bg-[#EAEAEA] min-h-screen w-full">
					<div className="max-sm:mb-3 pl-7 pt-5 max-sm:pt-7  max-sm:pl-7 flex justify-start"></div>
					{/*  CONTACT Form START */}
					<div className="sm:bg-gray-200 min-h-screen">
						<div className="flex bg-gray-200 overflow-x-hidden justify-between px-5">
							<div className="border-2 rounded-2xl bg-white shadow-inner flex w-[90%] m-5 mx-auto">
								<div className="flex flex-col mx-10 max-sm:mx-0 max-sm:ml-10  mt-0  ">
									<div class="flex justify-start my-2   gap-x-6">
										<div className="flex flex-col justify-start ">
											<h2 className=" max-sm:mb-0 font-semibold mt-7 max-sm:mt-10 mb-2">Job Title</h2>
											<input name="jobTitle" id="jobtitle" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300" type="text" placeholder="Product Name" />
										</div>
										<div className="flex flex-col justify-start ">
											<h2 className=" max-sm:mb-0 font-semibold mt-7 max-sm:mt-10 mb-2">Job Category</h2>
											<input name="jobCategory" id="jobCategory" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300" type="text" placeholder="Category" />
										</div>
										<div className="flex flex-col justify-start ">
											<h2 className=" max-sm:mb-0 font-semibold mt-7 max-sm:mt-10 mb-2">Requisition Number</h2>
											<input name="requisitionNumber" id="requisitionNumber" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300" type="text" placeholder="Requisition No." />
										</div>
										{/* <div className="max-sm:absolute flex max-sm:mt-32 max-sm:flex-col max-sm:justify-start flex-col">
										<h2 className="font-semibold max-sm:mb-0 mt-7 mb-2">Write Content</h2>
										<textarea
											className="outline-none border-2 mr-96   rounded-lg max-sm:mr-0 text-sm p-2  w-96 max-sm:w-72 pr-32 my-2  "
											type="text"
											placeholder=""
											rows="5"
										/>
										</div> */}
									</div>
									<div>
										<div className="mb-5  max-sm:absolute max-sm:mt-28">
											<div className="flex items-center gap-x-6">
												<div>
													<h2 className="font-semibold  my-2 max-sm:mb-0 max-sm:mt-20">Select Schedule</h2>
													<input name="schedule" id="schedule" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300" type="text" placeholder="Select Schedule" />
												</div>
												<div>
													<h2 className="font-semibold  my-2 max-sm:mb-0 max-sm:mt-20">Description</h2>
													<input name="description" id="description" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300" type="text" placeholder="Description" />
												</div>
											</div>
											<h2 className="font-semibold absolute  max-sm:mb-0  mb-2">Write Content</h2>
											<div className="pl-44">
												<a href="/careers" className="text-[#004B95]  pl-96 underline cursor-pointer font-semibold absolute flex">
													View Uploaded Job List{" "}
													<span className="text-[#004B95] text-[25px]">
														<BsArrowRightShort />
													</span>
												</a>
											</div>
											<div id="editorContainer" className="w-[95%] mt-10">
												<div id="editor" style={{zoom:"140%"}}>
													<textarea id="edit" name="edit" className="opacity-0 min-h-[400px]"></textarea>
												</div>
											</div>
										</div>
										<div className="flex justify-center max-sm:absolute pl-96 mb-5 max-sm:pl-1 max-sm:pr-0 max-sm:my-4 max-sm:mt-44">
											<button className=" bg-[#A6A6A64D] text-black  max-sm:mb-5 max-sm:px-10 rounded-lg py-1 px-14">Cancel</button>
											<div className="mx-2">
												<button
													className=" max-sm:mb-5  bg-[#004B95] text-white max-sm:px-10  rounded-lg py-1 px-14"
													onClick={() => {
														let jobtitle = document.getElementById("jobtitle").value;
														let jobCategory = document.getElementById("jobCategory").value;
														let requisitionNumber = document.getElementById("requisitionNumber").value;
														let schedule = document.getElementById("schedule").value;
														let edit = document.getElementById("edit").value;
														let simpledescription = document.getElementById("description").value;
														if (jobtitle && jobCategory && requisitionNumber && schedule && edit && simpledescription) {
															let formData = new FormData();
															formData.append("jobtitle", jobtitle);
															formData.append("jobCategory", jobCategory);
															formData.append("requisitionNumber", requisitionNumber);
															formData.append("schedule", schedule);
															formData.append("edit", edit);
															formData.append("simpledescription", simpledescription);

															fetch(process.env.REACT_APP_SERVER + "/api/newCareer/", {
																method: "POST",
																body: formData,
															})
																.then((response) => response.json())
																.then((data) => {
																	console.log(data);
																	window.location.reload();
																});
														} else {
															alert("Please fill all the fields");
														}
													}}
												>
													Upload
												</button>
											</div>
										</div>
									</div>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>

			{/*  CONTACT Form END */}
		</>
	);
}
export default Job1;
