											let heading1 = document.getElementById("heading1").value;
											let heading2 = document.getElementById("heading2").value;
											let lableOfName = document.getElementById("lableOfName").value;
											let textFiledName = document.getElementById("textFiledName").value;
											let lableOfQuery = document.getElementById("lableOfQuery").value;
											let textFiledOfQuery = document.getElementById("textFiledOfQuery").value;
											let lableOfEmail = document.getElementById("lableOfEmail").value;
