												formData.append("heading1", heading1);
												formData.append("heading2", heading2);
												formData.append("lableOfName", lableOfName);
												formData.append("textFiledName", textFiledName);
												formData.append("lableOfQuery", lableOfQuery);
												formData.append("textFiledOfQuery", textFiledOfQuery);
												formData.append("lableOfEmail", lableOfEmail);
												formData.append("textFiledOfEmail", textFiledOfEmail);
												formData.append("lableOfAddress", lableOfAddress);
