import React, { useState } from "react";
import parse from "html-react-parser";
const Reviewcard1 = ({ data, id }) => {
	const [current, setCurrent] = useState(false);
	return (
		// for edit blog
		<div id={id} className={"relative flex flex-col group w-full overflow-hidden  h-[229px] rounded-lg bg-[#FFFFFF] shadow-lg border-[2px] hover:border-[#004B95] transition-all duration-300 "}>
			<div className="cursor-pointer  gap-[10px] h-[250px] flex justify-between   ">
				<img className="w-[50%] object-contain" src={process.env.REACT_APP_SERVER + data.image} alt="/" />
				<div className="pr-[22px]">
					<div className="flex justify-between pt-[10px] relative">
						<p className="font-semibold text-kijeka-blue text-[16px] w-[90%] text-left leading-[20px] tracking-[5%] duration-300 group-hover:scale-90">{data.title} </p>
						<div className=" flex flex-col items-center gap-4 mr-[2px] mb-[15px] bg-white rounded-lg shadow-lg p-3 z-30 duration-300 opacity-0 group-hover:opacity-100 translate-x-32 group-hover:translate-x-0 absolute right-0">
							{/* returns svg */}
							<svg width={22} height={22} viewBox="0 0 22 22" fill="none">
								<path d="M9.97124 0.905273H6.07645C2.87332 0.905273 0.86499 3.17298 0.86499 6.3834V15.0438C0.86499 18.2542 2.86395 20.5219 6.07645 20.5219H15.2681C18.4817 20.5219 20.4806 18.2542 20.4806 15.0438V10.848" stroke="#37A945" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
								<path fillRule="evenodd" clipRule="evenodd" d="M7.19565 9.37617L14.98 1.5918C15.9498 0.623047 17.5217 0.623047 18.4915 1.5918L19.7592 2.85951C20.729 3.8293 20.729 5.40221 19.7592 6.37096L11.9373 14.1928C11.5134 14.6168 10.9384 14.8553 10.3384 14.8553H6.43628L6.5342 10.9178C6.54878 10.3387 6.78524 9.78659 7.19565 9.37617Z" stroke="#37A945" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
								<path d="M13.7971 2.79492L18.5534 7.55117" stroke="#37A945" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
							</svg>
							<svg
								onClick={() => {
									setCurrent((prev) => !prev);
									let parent = document.getElementById(id);
									parent.classList.add("scale-0");
									setTimeout(() => {
										parent.remove();
										let newForm = new FormData();
										newForm.append("id", id.replace("review-", ""));
										newForm.append("status", "approved");
										fetch(process.env.REACT_APP_SERVER + "/api/underReviewBlogs/", {
											method: "post",
											body: newForm,
										})
											.then((res) => res.json())
											.then((res) => {
												console.log(res);
											});
									}, 300);
								}}
								width={30}
								height={30}
								viewBox="0 0 30 30"
								fill="none"
								xmlns="http://www.w3.org/2000/svg"
							>
								<path d="M25.375 14.5C25.375 20.5061 20.5061 25.375 14.5 25.375M25.375 14.5C25.375 8.4939 20.5061 3.625 14.5 3.625M25.375 14.5H3.625M14.5 25.375C8.4939 25.375 3.625 20.5061 3.625 14.5M14.5 25.375C14.5 25.375 19.3333 21.75 19.3333 14.5C19.3333 7.25 14.5 3.625 14.5 3.625M14.5 25.375C14.5 25.375 9.66667 21.75 9.66667 14.5C9.66667 7.25 14.5 3.625 14.5 3.625M3.625 14.5C3.625 8.4939 8.4939 3.625 14.5 3.625" stroke="#37A945" strokeWidth="2.5" />
							</svg>

							<svg
								onClick={() => {
									setCurrent((prev) => !prev);
									let parent = document.getElementById(id);
									parent.classList.add("scale-0");
									setTimeout(() => {
										parent.remove();
										let newForm = new FormData();
										newForm.append("id", id.replace("review-", ""));
										newForm.append("status", "rejected");
										fetch(process.env.REACT_APP_SERVER + "/api/underReviewBlogs/", {
											method: "post",
											body: newForm,
										})
											.then((res) => res.json())
											.then((res) => {
												console.log(res);
											});
									}, 300);
								}}
								xmlns="http://www.w3.org/2000/svg"
								width="25"
								height="25"
								fill="#FF7E48"
								class="bi bi-x-circle"
								viewBox="0 0 16 16"
							>
								<path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
								<path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
							</svg>

							<svg
								onClick={() => {
									setCurrent((prev) => !prev);
									let parent = document.getElementById(id);
									parent.classList.add("scale-0");
									setTimeout(() => {
										parent.remove();
										fetch(process.env.REACT_APP_SERVER + "/api/underReviewBlogs/?id=" + id.replace("review-", ""), { method: "DELETE" })
											.then((res) => res.json())
											.then((res) => {
												console.log(res);
											});
									}, 300);
								}}
								width={19}
								height={21}
								viewBox="0 0 19 21"
								fill={current === false ? "none" : "red "}
							>
								<path d="M16.3249 7.54004C16.3249 7.54004 15.7819 14.275 15.4669 17.112C15.3169 18.467 14.4799 19.261 13.1089 19.286C10.4999 19.333 7.88791 19.336 5.27991 19.281C3.96091 19.254 3.13791 18.45 2.99091 17.119C2.67391 14.257 2.13391 7.54004 2.13391 7.54004" stroke={"red "} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
								<path d="M17.7082 4.31152H0.750244" stroke={"red "} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
								<path d="M14.4407 4.31127C13.6557 4.31127 12.9797 3.75627 12.8257 2.98727L12.5827 1.77127C12.4327 1.21027 11.9247 0.822266 11.3457 0.822266H7.1127C6.5337 0.822266 6.0257 1.21027 5.8757 1.77127L5.6327 2.98727C5.4787 3.75627 4.8027 4.31127 4.0177 4.31127" stroke={"red "} strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" />
							</svg>
						</div>
					</div>
					<p className="font-poppins group-hover:transform group-hover:scale-95  duration-300  text-left text-[11px] pt-[5px] tracking-[6%] font-medium w-full overflow-hidden h-full  ">{parse(data.description)}</p>
				</div>
			</div>
			<div className="absolute bottom-0 left-0 flex justify-between items-center rounded-b-lg bg-white shadow-inner  w-[50%] h-fit group-hover:translate-y-0 translate-y-[100%] ease-out duration-300  ">
				<div className="flex">
					<img className="object-cover object-center w-14 h-14 p-2  rounded-full shadow-[#D8D8D880]" src={"/static/images/logoOnly.png"} alt="/" />
					<div className="pl-2 pt-2">
						<p className="font-poppins font-medium text-[16px] leading-[24px] tracking-[5%] text-[#000000]">{data.author}</p>
						<p className="font-poppins font-medium text-[8px]  leading-[12px] tracking-[5%] text-[#000000] ">{data.date}</p>
					</div>
				</div>
			</div>
		</div>
	);
};

export default Reviewcard1;
