import React, { useState } from "react";
import { dashJobInqTitle, dashJobInqData } from "../../../lib/constants/index";
import { historyDivClass, tableClass, historyCardDivClass } from "../../../lib/constants/classes";
import { BiChevronDown } from "react-icons/bi";
import axios from "axios";

const JobInquires = ({ conatctData }) => {
	const [modelData, setModelData] = useState({
		id: "id",
		name: "name",
		email: "email",
		phone: "phone",
		country: "country",
		company: "company",
		query: "query",
		address: "address",
		suscribed: true,
	});
	return (
		<div className={historyDivClass} id="ContactUsQueryTable">
			{/* Job Inquiries table */}
			<div className="w-full h-full fixed top-0 left-0 bg-black/50 z-50 flex items-center justify-center scale-0 opacity-0 transition-all duration-300" id="contactQueryOverlay">
				<div className="w-1/2 max-w-[600px] bg-white rounded-lg p-5 relative">
					<div
						className="absolute -top-4 -right-3 bg-white shadow-xl rounded-full p-1 cursor-pointer"
						onClick={() => {
							document.getElementById("contactQueryOverlay").classList.add("scale-0", "opacity-0");
							document.getElementById("inquiryQueryTable").style.zIndex = "30";
						}}
					>
						<svg xmlns="http://www.w3.org/2000/svg" width="25" height="25" fill="#004B95" className="bi bi-x-circle" viewBox="0 0 16 16">
							<path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
							<path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
						</svg>
					</div>
					<div className="grid grid-cols-2 gap-3">
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm">
								Name : <span className="text-gray-500 font-medium">{modelData["name"]}</span>
							</p>
						</div>
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm">
								Email : <span className="text-gray-500 font-medium trucate">{modelData["email"]}</span>
							</p>
						</div>
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm">
								Phone : <span className="text-gray-500 font-medium">{modelData["phone"]}</span>
							</p>
						</div>
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm">
								Country : <span className="text-gray-500 font-medium">{modelData["country"]}</span>
							</p>
						</div>
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm">
								Company : <span className="text-gray-500 font-medium">{modelData["company"]}</span>
							</p>
						</div>
						<div className="">
							<p className="text-kijeka-blue font-semibold text-sm flex items-center">
								Suscribed :
								{modelData["suscribed"] ? (
									<svg xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink" width="15px" height="15px" viewBox="0,0,256,256" className="scale-150 ml-2">
										<g fill="none" fillRule="nonzero" stroke="none" strokeWidth={1} strokeLinecap="butt" strokeLinejoin="miter" strokeMiterlimit={10} strokeDasharray="" strokeDashoffset={0} fontFamily="none" fontWeight="none" fontSize="none" textAnchor="none" style={{ mixBlendMode: "normal" }}>
											<g transform="scale(5.33333,5.33333)">
												<path d="M44,24c0,11.045 -8.955,20 -20,20c-11.045,0 -20,-8.955 -20,-20c0,-11.045 8.955,-20 20,-20c11.045,0 20,8.955 20,20z" fillOpacity={0.27843} fill="#004b95" />
												<path d="M34.586,14.586l-13.57,13.586l-5.602,-5.586l-2.828,2.828l8.434,8.414l16.395,-16.414z" fill="#004b95" />
											</g>
										</g>
									</svg>
								) : (
									<svg xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink" width="13px" height="13px" viewBox="0,0,256,256" className="scale-150 ml-2">
										<g transform="">
											<g fill="none" fillRule="nonzero" stroke="none" strokeWidth={1} strokeLinecap="butt" strokeLinejoin="miter" strokeMiterlimit={10} strokeDasharray="" strokeDashoffset={0} fontFamily="none" fontWeight="none" fontSize="none" textAnchor="none" style={{ mixBlendMode: "normal" }}>
												<g>
													<circle cx={128} cy={128} r={125} fillOpacity={0.2} fill="#950000" />
													<path d="M155.053,128l43.439,-43.439c2.656,-2.656 2.656,-6.963 0,-9.619l-17.434,-17.434c-2.656,-2.656 -6.963,-2.656 -9.619,0l-43.439,43.439l-43.439,-43.438c-2.656,-2.656 -6.963,-2.656 -9.619,0l-17.433,17.434c-2.656,2.656 -2.656,6.963 0,9.619l43.438,43.438l-43.439,43.439c-2.656,2.656 -2.656,6.963 0,9.619l17.434,17.434c2.656,2.656 6.963,2.656 9.619,0l43.439,-43.439l43.439,43.439c2.656,2.656 6.963,2.656 9.619,0l17.434,-17.434c2.656,-2.656 2.656,-6.963 0,-9.619z" fill="#cd0000" />
													<path d="M128,255c-70.028,0 -127,-56.972 -127,-127c0,-70.028 56.972,-127 127,-127c70.028,0 127,56.972 127,127c0,70.028 -56.972,127 -127,127zM128,5c-67.822,0 -123,55.178 -123,123c0,67.822 55.178,123 123,123c67.822,0 123,-55.178 123,-123c0,-67.822 -55.178,-123 -123,-123z" fillOpacity={0} fill="#004b95" />
													<path
														d="M176.248,202.483c-2.351,0 -4.561,-0.916 -6.224,-2.578l-42.024,-42.024l-42.025,42.024c-1.662,1.663 -3.872,2.578 -6.223,2.578c-2.351,0 -4.562,-0.916 -6.224,-2.578l-17.434,-17.434c-3.431,-3.432 -3.431,-9.016 0,-12.447l42.025,-42.024l-42.025,-42.024c-3.431,-3.432 -3.431,-9.016 0,-12.447l17.435,-17.434c1.662,-1.663 3.873,-2.578 6.224,-2.578c2.351,0 4.561,0.916 6.224,2.578l42.023,42.024l42.025,-42.024c1.662,-1.663 3.872,-2.578 6.223,-2.578c2.351,0 4.562,0.916 6.224,2.578l17.434,17.434c3.431,3.432 3.431,9.016 0,12.447l-42.025,42.024l42.024,42.024c3.431,3.432 3.431,9.016 0,12.447l-17.435,17.434c-1.66,1.663 -3.871,2.578 -6.222,2.578zM128,153.053c0.512,0 1.024,0.195 1.414,0.586l43.439,43.438c0.907,0.907 2.113,1.406 3.395,1.406c1.283,0 2.488,-0.5 3.396,-1.406l17.434,-17.434c1.872,-1.872 1.872,-4.919 0,-6.791l-43.438,-43.438c-0.375,-0.375 -0.586,-0.884 -0.586,-1.414c0,-0.53 0.211,-1.039 0.586,-1.414l43.439,-43.438c1.872,-1.872 1.872,-4.919 0,-6.791l-17.434,-17.434c-0.907,-0.907 -2.113,-1.406 -3.396,-1.406c-1.282,0 -2.488,0.5 -3.395,1.406l-43.439,43.438c-0.78,0.781 -2.048,0.781 -2.828,0l-43.44,-43.438c-0.907,-0.907 -2.113,-1.406 -3.395,-1.406c-1.283,0 -2.488,0.5 -3.396,1.406l-17.434,17.433c-1.872,1.872 -1.872,4.919 0,6.791l43.438,43.438c0.375,0.375 0.586,0.884 0.586,1.414c0,0.53 -0.211,1.039 -0.586,1.414l-43.439,43.438c-1.872,1.872 -1.872,4.919 0,6.791l17.434,17.434c0.907,0.907 2.113,1.406 3.396,1.406c1.282,0 2.488,-0.5 3.395,-1.406l43.439,-43.438c0.391,-0.39 0.903,-0.585 1.415,-0.585z"
														fillOpacity={0}
														fill="#004b95"
													/>
												</g>
											</g>
										</g>
									</svg>
								)}
							</p>
						</div>
					</div>
					<div className="my-3">
						<p className="text-kijeka-blue font-semibold text-sm">
							Query : <span className="text-gray-500 font-medium">{modelData["query"]}</span>
						</p>
					</div>
					<div className="">
						<p className="text-kijeka-blue font-semibold text-sm">
							Address : <span className="text-gray-500 font-medium">{modelData["address"]}</span>
						</p>
					</div>
					<div className="mt-5 flex items-center gap-3">
						<button
							onClick={() => {
								document.getElementById("Job-" + modelData.id).classList.add("-translate-x-[100%]");
								setTimeout(() => {
									document.getElementById("Job-" + modelData.id).remove();
									const indexes = document.getElementsByClassName("jobIndex");
									axios
										.delete(process.env.REACT_APP_SERVER + "/api/contactData?id=" + modelData.id)
										.then((res) => {
											console.log(res);
										})
										.catch((err) => {
											console.log(err);
										});
									if (indexes.length > 0) {
										for (let i = 0; i < indexes.length; i++) {
											indexes[i].innerHTML = (i + 1).toString() + ".";
										}
									} else {
										document.getElementById("jobTable").classList.add("hidden");
										document.getElementById("noJobData").classList.remove("hidden");
										document.getElementById("noJobData").classList.add("flex");
									}
									document.getElementById("contactQueryOverlay").classList.add("scale-0", "opacity-0");
									document.getElementById("inquiryQueryTable").style.zIndex = "30";
								}, 300);
							}}
							className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
						>
							Delete
						</button>
						<a href={"mailto:" + modelData.email + "?subject=This mail is regarding your query : " + modelData.query + "&body=Hello!"} className="bg-white hover:bg-[#37A945] text-kijeka-blue border-1 border-kijeka-blue hover:border-[#37A945] hover:text-white font-medium text-description px-6 py-2 rounded-lg cursor-pointer transition-all duration-300">
							Contact
						</a>
					</div>
				</div>
			</div>
			<div className="flex items-center justify-between px-5 pt-5 sticky bg-white top-0 z-30">
				<p className="font-bold text-title text-sidebar">Contact Us</p>
				<div
					onClick={() => {
						document.getElementById("tworecentdw").classList.toggle("scale-y-0");
						document.getElementById("tworecentdw").classList.toggle("opacity-0");
					}}
					onBlur={() => {
						document.getElementById("tworecentdw").classList.add("scale-y-0");
						document.getElementById("tworecentdw").classList.add("opacity-0");
					}}
					className="border-[1px] border-sidebar py-1 px-3 rounded-lg flex items-center justify-between cursor-pointer"
				>
					<p className="font-semibold text-subtitle text-sidebar">Recent</p>
					<BiChevronDown className=" h-7 w-7 text-sidebar" aria-hidden="true" />

					{/* Recent Overlay */}
					<div
						className="bg-white border-[1px] backdrop-blur absolute top-16 right-4 z-50 scale-y-0 opacity-0 origin-top transition-all duration-300 w-max min-w-[10rem] rounded-lg"
						id="tworecentdw"
						onMouseLeave={() => {
							document.getElementById("tworecentdw").classList.add("scale-y-0");
							document.getElementById("tworecentdw").classList.add("opacity-0");
						}}
					>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Last Week</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Last 15 Days</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Last Months</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Last 2 Months</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Last 3 Months</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">View More</p>
					</div>
				</div>
			</div>
			<div>
				<table id="jobTable" className={"table-auto border-spacing-0 border-collapse w-full  max-h-[450px] h-fit overflow-y-scroll"}>
					<tr className="text-kijeka-blue px-3 sticky top-[3.6rem] bg-white z-20">
						{dashJobInqTitle.map((item, index) => {
							if (item.type !== "checkbox") {
								return (
									<td key={index} className="px-0 pb-4 pt-6 text-center">
										{item.title}
									</td>
								);
							} else {
								return (
									<td key={index} className="px-0 pb-4 pt-6 text-center ">
										{item.title}
										<input type="checkbox" className="ml-2 pt-2 scale-110" />
									</td>
								);
							}
						})}
					</tr>
					{conatctData.map((item, index) => {
						return (
							<tr
								key={index}
								id={"Job-" + item.id}
								data-name={item.name}
								data-email={item.email}
								data-phone={item.phoneNo}
								data-country={item.country}
								data-company={item.companyName}
								data-query={item.query}
								data-address={item.address}
								data-suscribed={item.isSuscribed}
								className={historyCardDivClass + " py-3 text-center px-3 border-y-2 transition-all duration-300"}
								onMouseLeave={() => {
									document.getElementById("2-Contact-" + index).classList.remove("translate-x-[400px]");
									// document.getElementById("2-Resume-" + index).classList.remove("translate-x-[400px]");
									document.getElementById("2-Delete-" + index).classList.add("translate-x-[400px]");
								}}
								onClick={() => {
									document.getElementById("inquiryQueryTable").style.zIndex = "0";
									document.getElementById("contactQueryOverlay").classList.remove("scale-0", "opacity-0");
									setModelData({
										id: item.id,
										name: item.name,
										email: item.email,
										phone: item.phoneNo,
										country: item.country,
										company: item.companyName,
										query: item.query,
										address: item.address,
										suscribed: item.isSuscribed,
									});
								}}
							>
								<td className="w-1/6">
									<p className="text-[12px] text-kijeka-blue font-semibold jobIndex">{index + 1}.</p>
								</td>
								<td className="w-5/6 text-justify">
									<p className="text-[12px] text-kijeka-blue font-bold">
										{item.name} - <span className="font-normal">{item.query}</span>
									</p>
								</td>
								<td className="flex  items-center gap-2 mx-auto w-max px-3 h-full py-5 relative overflow-hidden">
									<a href={"mailto:" + item.email + "?subject=This mail is regarding your query : " + item.query + "&body=Hello!"} id={"2-Contact-" + index} className="text-kijeka-blue hover:bg-[#37A945] hover:border-0 hover:text-white cursor-pointer border-[1px] border-kijeka-blue py-1 px-4 rounded-full w-max z-10 transition-all duration-300">
										<p className="text-[10px] font-semibold">Contact</p>
									</a>
									{/* <div id={"2-Resume-" + index} className="hover:bg-[#37A945] cursor-pointer border-[1px] bg-kijeka-blue py-1 px-4 rounded-full w-max z-10 transition-all duration-300">
									<p className="text-white text-[10px] font-semibold">Resume</p>
								</div> */}
									<div
										id={"2-Delete-" + index}
										className="bg-[#F21818] w-20 h-full translate-x-[400px] absolute right-0 transition-all duration-300 flex items-center justify-center cursor-pointer"
										onMouseLeave={() => {
											document.getElementById("2-Contact-" + index).classList.remove("translate-x-[400px]");
											// document.getElementById("2-Resume-" + index).classList.remove("translate-x-[400px]");
											document.getElementById("2-Delete-" + index).classList.add("translate-x-[400px]");
										}}
										onClick={() => {
											document.getElementById("Job-" + item.id).classList.add("-translate-x-[100%]");
											setTimeout(() => {
												document.getElementById("Job-" + item.id).remove();
												const indexes = document.getElementsByClassName("jobIndex");
												axios
													.delete(process.env.REACT_APP_SERVER + "/api/contactData?id=" + item.id)
													.then((res) => {
														console.log(res);
													})
													.catch((err) => {
														console.log(err);
													});
												if (indexes.length > 0) {
													for (let i = 0; i < indexes.length; i++) {
														indexes[i].innerHTML = (i + 1).toString() + ".";
													}
												} else {
													document.getElementById("jobTable").classList.add("hidden");
													document.getElementById("noJobData").classList.remove("hidden");
													document.getElementById("noJobData").classList.add("flex");
												}
											}, 300);
										}}
									>
										<svg xmlns="http://www.w3.org/2000/svg" width="18" height="20" viewBox="0 0 18 20" fill="none">
											<path
												fill-rule="evenodd"
												clip-rule="evenodd"
												d="M17.2871 3.24297C17.6761 3.24297 18 3.56596 18 3.97696V4.35696C18 4.75795 17.6761 5.09095 17.2871 5.09095H0.713853C0.32386 5.09095 0 4.75795 0 4.35696V3.97696C0 3.56596 0.32386 3.24297 0.713853 3.24297H3.62957C4.22185 3.24297 4.7373 2.82197 4.87054 2.22798L5.02323 1.54598C5.26054 0.616994 6.0415 0 6.93527 0H11.0647C11.9488 0 12.7385 0.616994 12.967 1.49699L13.1304 2.22698C13.2627 2.82197 13.7781 3.24297 14.3714 3.24297H17.2871ZM15.8058 17.134C16.1102 14.2971 16.6432 7.55712 16.6432 7.48913C16.6626 7.28313 16.5955 7.08813 16.4623 6.93113C16.3193 6.78413 16.1384 6.69713 15.9391 6.69713H2.06852C1.86818 6.69713 1.67756 6.78413 1.54529 6.93113C1.41108 7.08813 1.34494 7.28313 1.35467 7.48913C1.35646 7.50162 1.37558 7.73903 1.40755 8.13594C1.54958 9.89917 1.94517 14.8102 2.20079 17.134C2.38168 18.846 3.50498 19.922 5.13206 19.961C6.38763 19.99 7.68112 20 9.00379 20C10.2496 20 11.5149 19.99 12.8094 19.961C14.4929 19.932 15.6152 18.875 15.8058 17.134Z"
												fill="white"
											/>
										</svg>
									</div>
									<div
										className="absolute right-0 w-6 h-full z-0 "
										onMouseEnter={() => {
											document.getElementById("2-Contact-" + index).classList.add("translate-x-[400px]");
											// document.getElementById("2-Resume-" + index).classList.add("translate-x-[400px]");
											document.getElementById("2-Delete-" + index).classList.remove("translate-x-[400px]");
										}}
									></div>
								</td>
							</tr>
						);
					})}
				</table>
				<div id="noJobData" className={`hidden w-full h-full items-center justify-center py-10`}>
					<span className="text-kijeka-blue font-poppins text-xl font-bold w-fit">NO DATA FOUND </span>
				</div>
			</div>
		</div>
	);
};

export default JobInquires;
