import React, { useState, useEffect } from "react";
import { BiChevronDown } from "react-icons/bi";
import axios from "axios";

const Users = () => {
    document.title = "Kijeka | Users";

    const [selectedUsersDropdown, setSelectedUsersDropdown] = useState("Recent");
    const [searchUser, setSearchUser] = useState("");
    const [users, setUsers] = useState([]);
    const [access, setAccess] = useState([]);

    if (users.length === 0) {
        axios
            .get(process.env.REACT_APP_SERVER + "/api/userList/")
            .then((data) => setUsers(data["data"]["data"]))
            .catch((error) => console.log(error));
    }

    return (
        <div className="w-full bg-[#EAEAEA] min-h-[calc(100vh-80px)] pb-6 md:px-12 py-4 px-4">
            <div className="">
                <p className="text-kijeka-blue font-bold text-title">Users</p>
            </div>
            {/* Searchbar */}
            <div className="w-full flex justify-end">
                <div className="relative">
                    <input
                        type="text"
                        placeholder="Search user..."
                        className="bg-white text-kijeka-blue outline-none p-2 px-4 placeholder:text-kijeka-blue w-full shadow-[0px_4px_16px_0px_rgba(166,166,166,0.20)] rounded-lg"
                        onChange={(event) => {
                            setSearchUser(event.currentTarget.value);
                        }}
                    />
                    <svg viewBox="0 0 21 22" fill="none" className="w-5 h-5 absolute top-1/2 -translate-y-1/2 right-4">
                        <circle cx={7.763} cy={8.424} r={6.763} stroke="#004B95" strokeWidth={2} />
                        <path d="M14.525 15.187 20 20.338" stroke="#004B95" strokeWidth={2} strokeLinecap="round" />
                    </svg>
                </div>
            </div>
            <div className="my-5 bg-white rounded-lg shadow-[0px_2px_20px_rgba(166,166,166,0.25)] md:p-5 px-5">
                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-kijeka-blue font-semibold text-lg">ADD New User</p>
                    </div>
                    {/* Recent Dropdown */}
                    <div
                        onClick={() => {
                            document.getElementById("usersDropdown").classList.toggle("scale-y-0");
                            document.getElementById("usersDropdown").classList.toggle("opacity-0");
                        }}
                        onBlur={() => {
                            document.getElementById("usersDropdown").classList.add("scale-y-0");
                            document.getElementById("usersDropdown").classList.add("opacity-0");
                        }}
                        className="border-[1px] border-sidebar py-1 px-3 rounded-lg flex items-center justify-between cursor-pointer relative"
                    >
                        <p className="font-semibold text-subtitle text-sidebar">{selectedUsersDropdown}</p>
                        <BiChevronDown className=" h-7 w-7 text-sidebar" aria-hidden="true" />

                        {/* Recent Overlay */}
                        <div
                            className="bg-white border-[1px] backdrop-blur absolute top-10 right-0 z-50 scale-y-0 opacity-0 origin-top transition-all duration-300 w-max min-w-[10rem] rounded-lg"
                            id="usersDropdown"
                            onMouseLeave={() => {
                                document.getElementById("usersDropdown").classList.add("scale-y-0");
                                document.getElementById("usersDropdown").classList.add("opacity-0");
                            }}
                        >
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Recent");
                                }}
                            >
                                Recent
                            </p>
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Last Week");
                                }}
                            >
                                Last Week
                            </p>
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Last 15 Days");
                                }}
                            >
                                Last 15 Days
                            </p>
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Last Months");
                                }}
                            >
                                Last Months
                            </p>
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Last 2 Months");
                                }}
                            >
                                Last 2 Months
                            </p>
                            <p
                                className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:text-[#37A945] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
                                onClick={() => {
                                    setSelectedUsersDropdown("Last 3 Months");
                                }}
                            >
                                Last 3 Months
                            </p>
                        </div>
                    </div>
                </div>
                <div className="grid grid-cols-1 grid-rows-2 lg:grid-cols-2 lg:grid-rows-1 gap-4 mt-4">
                    {/* Left Side */}
                    <div className="w-full h-auto pb-5 lg:pb-0 border-b-2 lg:border-b-0 lg:border-r-2 border-[#A6A6A64D] px-4">
                        <div className="w-full grid grid-cols-2 gap-5">
                            <div className="w-full">
                                <p className="font-medium">First Name</p>
                                <input type="text" id="firstName" name="firstName" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300" placeholder="First name" />
                            </div>
                            <div className="w-full">
                                <p className="font-medium">Last Name</p>
                                <input type="text" id="lastName" name="lastName" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300" placeholder="Last name" />
                            </div>
                        </div>
                        <div className="w-full grid grid-cols-2 gap-5 my-8">
                            <div className="w-full">
                                <p className="font-medium">Email Id</p>
                                <input type="text" id="userEmail" name="userEmail" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300" placeholder="Email Id" />
                            </div>
                            <div className="w-full">
                                <p className="font-medium">Job Role</p>
                                <select name="jobRole" id="jobRole" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300">
                                    <option value="" selected disabled>
                                        Select Job Role
                                    </option>
                                    <option value="admin">Admin</option>
                                    <option value="blog">Blog</option>
                                    <option value="inquiry">Inquiry</option>
                                </select>
                            </div>
                            <input type="hidden" id="userId" name="userId" />
                        </div>
                        {access.length !== 0 && (
                            <div className="my-4">
                                <p className="text-kijeka-blue font-semibold text-lg">Can Access</p>
                            </div>
                        )}
                        <div className="w-full grid grid-cols-2 gap-5">
                            {access.map((item, index) => (
                                <div key={index} className="flex items-center gap-2">
                                    <svg className="w-5 h-5 text-kijeka-blue" viewBox="0 0 24 24" data-name="Flat Line" xmlns="http://www.w3.org/2000/svg">
                                        <path
                                            style={{
                                                fill: "none",
                                                stroke: "currentColor",
                                                strokeLinecap: "round",
                                                strokeLinejoin: "round",
                                                strokeWidth: 2,
                                            }}
                                            d="m5 12 5 5 9-9"
                                        />
                                    </svg>
                                    <label htmlFor="canViewAdminDashboard">Can Use {item}</label>
                                </div>
                            ))}
                        </div>
                        <div className="flex items-center justify-end gap-3 mt-4">
                            <button
                                className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
                                onClick={() => {
                                    document.getElementById("firstName").value = "";
                                    document.getElementById("lastName").value = "";
                                    // document.getElementById("userId").value = "";
                                    document.getElementById("userEmail").value = "";
                                    // document.getElementById("userContact").value = "";
                                    document.getElementById("jobRole").value = "";
                                    document.getElementById("userId").value = "";
                                    setAccess([]);
                                }}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => {
                                    let data = new FormData();
                                    data.append("firstName", document.getElementById("firstName").value);
                                    data.append("lastName", document.getElementById("lastName").value);
                                    data.append("email", document.getElementById("userEmail").value);
                                    data.append("role", document.getElementById("jobRole").value);
                                    data.append("userId", document.getElementById("userId").value);

                                    axios
                                        .post(process.env.REACT_APP_SERVER + "/api/userList/", data)
                                        .then((response) => {
                                            if (Object.keys(response.data).includes("msg")) {
                                                alert("User Added Successfully");
                                                window.location.reload();
                                            } else {
                                                alert(response.data.error);
                                            }
                                        })
                                        .catch((error) => {
                                            console.log(error);
                                        });
                                }}
                                className="bg-white hover:bg-[#37A945] text-kijeka-blue border-1 border-kijeka-blue hover:border-[#37A945] hover:text-white font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
                            >
                                Save
                            </button>
                        </div>
                    </div>
                    {/* Right Side */}
                    <div className="w-full h-full px-4">
                        <div className="">
                            <p className="text-kijeka-blue font-semibold text-lg">Added Users</p>
                        </div>
                        <div className="my-3 max-h-[600px] overflow-y-scroll no-scrollbar p-2" id="userList">
                            {users.map((item, index) => {
                                let data = item.firstName + " " + item.lastName + " " + item.email + " " + item.role + " " + item.access;
                                if (data.toLocaleLowerCase().includes(searchUser.toLocaleLowerCase())) {
                                    return (
                                        <div key={index} id={"user" + item.id} className={"bg-white shadow-[0px_2px_5px_0px_rgba(166,166,166,0.25)] p-5 rounded-lg flex items-center justify-between my-4 first-of-type:mt-0 last-of-type:mb-0 transition-all duration-300 "}>
                                            <div className="flex items-center gap-5 max-w-[70%] overflow-hidden">
                                                <div>
                                                    <p className="text-xl text-kijeka-blue font-bold userIndex">{index + 1}.</p>
                                                </div>
                                                <div>
                                                    <p className="text-lg font-bold text-kijeka-blue">
                                                        {item.firstName} {item.lastName} - {item.role}
                                                    </p>
                                                    <div className="flex items-center justify-between gap-2 text-sm my-2">
                                                        <p>
                                                            <span className="font-bold">Email</span> : {item.email}
                                                        </p>
                                                    </div>
                                                    <div className="text-kijeka-blue">
                                                        <p>
                                                            <span className="font-bold">Access </span>:&nbsp;{item.access}
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <div
                                                    className="bg-kijeka-blue py-3 px-6 rounded-full text-white cursor-pointer"
                                                    onClick={() => {
                                                        document.getElementById("firstName").value = item.firstName;
                                                        document.getElementById("lastName").value = item.lastName;
                                                        document.getElementById("userEmail").value = item.email;
                                                        document.getElementById("jobRole").value = item.role;
                                                        document.getElementById("userId").value = item.id;
                                                        setAccess(item.access.split(", "));
                                                    }}
                                                >
                                                    <p>Edit User</p>
                                                </div>
                                                <div
                                                    className="cursor-pointer"
                                                    onClick={() => {
                                                        axios
                                                            .delete(process.env.REACT_APP_SERVER + "/api/userList?userId=" + item.id)
                                                            .then((data) => {
                                                                if (Object.keys(data["data"]).includes("msg")) {
                                                                    document.getElementById("user" + item.id).classList.add("-translate-x-full");
                                                                    setTimeout(() => {
                                                                        document.getElementById("user" + item.id).remove();
                                                                        const indexes = document.getElementsByClassName("userIndex");
                                                                        if (indexes.length > 0) {
                                                                            for (let i = 0; i < indexes.length; i++) {
                                                                                indexes[i].innerHTML = (i + 1).toString() + ".";
                                                                            }
                                                                        } else {
                                                                            document.getElementById("userList").classList.add("hidden");
                                                                            document.getElementById("noDataFound").classList.remove("hidden");
                                                                        }
                                                                        alert("User Deleted Successfully");
                                                                    }, 300);
                                                                } else {
                                                                    alert(data["data"]["error"]);
                                                                }
                                                            })
                                                            .catch((error) => console.log(error));
                                                    }}
                                                >
                                                    <svg viewBox="0 0 21 22" fill="none" className="w-7 h-7">
                                                        <path fillRule="evenodd" clipRule="evenodd" d="M17.614 8.734s-.544 6.752-.86 9.596c-.15 1.358-.99 2.154-2.364 2.18-2.616.047-5.234.05-7.849-.006-1.322-.027-2.147-.833-2.294-2.167-.318-2.869-.86-9.603-.86-9.603" fill="#E52F2F" />
                                                        <path d="M17.614 8.734s-.544 6.752-.86 9.596c-.15 1.358-.99 2.154-2.364 2.18-2.616.047-5.234.05-7.849-.006-1.322-.027-2.147-.833-2.294-2.167-.318-2.869-.86-9.603-.86-9.603" stroke="#E52F2F" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" />
                                                        <path fillRule="evenodd" clipRule="evenodd" d="M19 5.5H2h17Z" fill="#E52F2F" />
                                                        <path d="M19 5.5H2" stroke="#E52F2F" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" />
                                                        <path fillRule="evenodd" clipRule="evenodd" d="M15.724 5.498a1.652 1.652 0 0 1-1.619-1.328l-.243-1.219A1.283 1.283 0 0 0 12.622 2H8.377c-.58 0-1.09.389-1.24.951l-.244 1.22a1.652 1.652 0 0 1-1.619 1.327" fill="#E52F2F" />
                                                        <path d="M15.724 5.498a1.652 1.652 0 0 1-1.619-1.328l-.243-1.219A1.283 1.283 0 0 0 12.622 2H8.377c-.58 0-1.09.389-1.24.951l-.244 1.22a1.652 1.652 0 0 1-1.619 1.327" stroke="#E52F2F" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" />
                                                    </svg>
                                                </div>
                                            </div>
                                        </div>
                                    );
                                }
                            })}
                        </div>
                        <div className="my-3 max-h-[600px] h-[600px] overflow-hidden flex items-center justify-center hidden" id="noDataFound">
                            <p className="text-xl text-kijeka-blue font-bold">No Data Found</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Users;
