import React, { useState } from "react";
import Select from "react-select";
import axios from "axios";
import Goback from "../Drafts/Goback";

const NewBlog = () => {
	//Text Editor Logic
	const javaScripts = ["https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/codemirror.min.js", "https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/mode/xml/xml.min.js", "/static/js/froala_editor.min.js", "/static/js/output.min.js", "/static/js/editorLoader.js"];
	const [category, setCategory] = useState([]);
	for (let i = 0; i < javaScripts.length; i++) {
		let element = javaScripts[i];
		let script = document.createElement("script");
		script.src = element;
		script.type = "text/javascript";
		document.body.appendChild(script);
	}

	if (category.length === 0) {
		axios
			.get(process.env.REACT_APP_SERVER + "/api/categoryList/")
			.then((data) => setCategory(data["data"]["data"]))
			.catch((error) => console.log(error));
	}
	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["New Blogs", "/dashboard/blog/newblog"],
				]}
			/>
			{/* new blog form */}
			<form action={process.env.REACT_APP_SERVER + "/api/addNewBlog/"} enctype="multipart/form-data" className="px-5 sm:px-20 pb-5" method="post">
				<div className="flex flex-col sm:flex-row gap-0 sm:gap-5 ">
					<div className="w-full sm:w-1/2">
						{/* title input box */}
						<div>
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Title</div>
							<input
								type="text"
								id="title"
								name="title"
								placeholder="Enter Title of Blog"
								className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200"
								required
								onChange={() => {
									document.getElementById("Bloglink").value = encodeURI(document.getElementById("title").value.replace(/ /g, "-").replace(/&/g, "and"));
								}}
							/>
						</div>
					</div>
					<div className="w-full sm:w-1/2">
						{/* Author input box */}
						<div>
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Author</div>
							<input type="text" id="author" name="author" placeholder="Enter Name of Author" className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200" required />
						</div>
					</div>
				</div>
				<div className="flex flex-col sm:flex-row gap-0 sm:gap-5 ">
					<div className="w-full sm:w-1/2">
						{/* category dropdown box */}
						<div className="mt-5">
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Category</div>
							<select id="category" name="category" className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200" required>
								{/* category options */}
								<option value="" className="text-kijeka-blue" disabled selected>
									Select Category
								</option>
								{category.map((item, index) => (
									<option key={index} value={item}>
										{item}
									</option>
								))}
							</select>
						</div>
					</div>
					<div className="w-full sm:w-1/2">
						{/* Bloglink input box */}
						<div className="mt-5">
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Bloglink</div>
							<input type="text" id="Bloglink" name="Bloglink" placeholder="Link of the blog" className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200" disabled required />
						</div>
					</div>
				</div>
				<div className="flex flex-col sm:flex-row gap-0 sm:gap-5 ">
					<div className="w-full sm:w-1/2">
						{/* image selection box */}
						<div className="mt-5">
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Image</div>
							<input id="image" name="image" type="file" className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200" required />
						</div>
					</div>
					<div className="w-full sm:w-1/2">
						{/* date input box */}
						<div className="mt-5">
							<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Date</div>
							<input id="date" name="date" type="date" className="w-full h-[3.25rem] border-2 border-kijeka-blue rounded-lg p-2 mt-2 focus:outline-none ring-0 focus:ring-2 focus:ring-kijeka-blue transition-all duration-200" required />
						</div>
					</div>
				</div>
				<div className="mt-5">
					{/* blog editor */}
					<div className="font-poppins font-medium text-subtitle tracking-wider text-kijeka-blue">Blog</div>
					<div id="editorContainer" className="w-full mt-2 ">
						<div id="editor" style={{zoom:"140%"}}>
							<textarea id="edit" name="edit" required></textarea>
						</div>
					</div>
				</div>
				<div className="flex justify-end mt-5">
					<div className="flex">
						<input onClick={(event)=>{
							if(document.getElementById("edit").value == "<!DOCTYPE html><html><head><title></title></head><body></body></html>")
							{
								event.preventDefault();
								alert("Please enter some content in the blog");
							}
						}} type="submit" value="Save To Draft"
							className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description p-2 rounded-lg cursor-pointer transition-all duration-300"
						/>
						{/* <button className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description p-2 rounded-lg cursor-pointer transition-all duration-300 ml-2">Publish</button> */}
					</div>
				</div>
			</form>
		</>
	);
};

export default NewBlog;
