import React, { useState, useEffect } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/free-mode";

import { FreeMode } from "swiper";
import EditCard from "./EditCard";
import RecentEdits from "./RecentEdits";
import Goback from "./Goback";
import DropDown from "../DropDown";
import axios from "axios";

const Drafts = () => {
	const [draftsData, setDraftsData] = useState([]);

	useEffect(() => {
		axios.get(process.env.REACT_APP_SERVER + "/api/blogDraft/").then((res) => {
			let data = res.data.data;
			setDraftsData(data);
		});
	}, []);

	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["Drafts", "/dashboard/blog/drafts"],
				]}
			/>
			<div className="px-12">
				<div className="flex justify-between items-center px-4 mb-10">{draftsData.length > 0 ? <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">All Drafts</p> : <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">No Drafts</p>}</div>
				{/* render all cards */}
				{draftsData.length > 0 ? (
					<div className="grid grid-cols-2 mt-[21px] gap-[51px] gap-y-6 pb-10">
						{draftsData.map((item, index) => {
							return <EditCard key={index} id={"draft-" + item["id"]} data={item} />;
						})}
					</div>
				) : (
					<></>
				)}
			</div>
		</>
	);
};

export default Drafts;
