import React from "react";
import axios from "axios";
const ProductCard = ({ name, img }) => {
	return (
		<div id={name} className="productCard bg-white p-4 rounded-xl shadow-xl border-2 border-transparent hover:border-kijeka-blue ">
			<div className="flex items-center justify-between">
				<p className="text-xs font-bold text-kijeka-blue tracking-wider truncate pr-3" title={name}>
					{name}
				</p>
			</div>
			<div className="flex justify-center my-2 max-h-32 min-h-32 h-32 object-contain">
				<img src={img} alt="" />
			</div>
			<div>
				<button
					onClick={() => {
						window.location.href = "/dashboard/add-products/?name=" + name;
					}}
					className="bg-kijeka-blue px-10 py-2 text-white text-[13px] font-semibold rounded-lg tracking-widest w-full my-2 outline-none hover:bg-[#37A945] transition-all duration-300"
				>
					Update
				</button>
				<button
					onClick={() => {
						if (window.confirm("Are you sure you want to remove this product?")) {
							axios
								.delete(process.env.REACT_APP_SERVER + "/api/removeProduct/?name=" + name)
								.then((data) => {
									if (data.data.msg) {
										alert("Product removed successfully");
										window.location.reload();
									} else {
										alert("Something went wrong");
									}
								})
								.catch((error) => console.log(error));
						}
					}}
					className="text-sm font-medium text-kijeka-blue w-full outline-none"
				>
					Remove
				</button>
			</div>
		</div>
	);
};

export default ProductCard;
