import React, { useState, useEffect } from "react";
import BlogsCardsClient from "../BlogsCardsClient";
import Goback from "../Drafts/Goback";
import DropDown from "../DropDown";
import axios from "axios";
const Published = () => {
	const [publishedData, setPublishedData] = useState([]);

	useEffect(() => {
		axios.get(process.env.REACT_APP_SERVER + "/api/approvedBlogs/").then((res) => {
			let data = res.data.data;
			setPublishedData(data);
		});
	}, []);

	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["Published", "/dashboard/blog/published"],
				]}
			/>
			<div className="px-12">
				<div className="flex justify-between items-center px-4 mb-10">{publishedData.length > 0 ? <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer  ">All Published Blogs</p> : <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer  ">No Published Blogs</p>}</div>
				{publishedData.length > 0 ? (
					<div className="grid grid-cols-2 mt-[21px] gap-[51px] gap-y-6 pb-10">
						{/* render all blog cards */}
						{publishedData.map((item, index) => {
							return <BlogsCardsClient key={index} id={"publish-" + item["id"]} data={item} />;
						})}
					</div>
				) : (
					<></>
				)}
			</div>
		</>
	);
};

export default Published;
