import React, { useState, useEffect } from "react";
import Goback from "../Drafts/Goback";
import DropDown from "../DropDown";
import RejectedCards from "./RejectedCards";
import axios from "axios";

const Rejected = () => {
	const [rejectedData, setRejectedData] = useState([]);

	useEffect(() => {
		axios.get(process.env.REACT_APP_SERVER + "/api/rejectedBlogs/").then((res) => {
			let data = res.data.data;
			setRejectedData(data);
		});
	}, []);

	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["Rejected", "/dashboard/blog/rejected"],
				]}
			/>

			<div className="px-12">
				<div className="flex justify-between items-center px-4 mb-10">{rejectedData.length > 0 ? <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">All Rejected Blogs</p> : <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">No Rejected Blogs</p>}</div>
				{rejectedData.length > 0 ? (
					<div className="grid grid-cols-2 mt-[21px] gap-[51px] gap-y-6 pb-10">
						{/* render all blog cards */}
						{rejectedData.map((item, index) => {
							return <RejectedCards key={index} id={"reject-" + item["id"]} data={item} />;
						})}
					</div>
				) : (
					<></>
				)}
			</div>
		</>
	);
};

export default Rejected;
