import React from "react";
import { FilePond, registerPlugin } from "react-filepond";
import "filepond/dist/filepond.min.css";
import FilePondPluginImageExifOrientation from "filepond-plugin-image-exif-orientation";
import FilePondPluginImagePreview from "filepond-plugin-image-preview";
import "filepond-plugin-image-preview/dist/filepond-plugin-image-preview.css";
import axios from "axios";

registerPlugin(FilePondPluginImageExifOrientation, FilePondPluginImagePreview);

const ImageSlider = () => {
	const [files, setFiles] = React.useState([]);
	const [images, setImages] = React.useState([]);

	if (images.length === 0) {
		axios.get(process.env.REACT_APP_SERVER + "/api/imageSlider/").then((res) => {
			let dataImage = res.data.data;
			setImages(dataImage);
			let tempArr = [];
			for (let i = 0; i < dataImage.length; i++) {
				if (dataImage[i] === "") {
					continue;
				} else {
					tempArr.push({
						source: process.env.REACT_APP_SERVER + dataImage[i],
					});
				}
			}
			setFiles(tempArr);
		});
	}

	React.useEffect(() => {
		document.title = "Kijeka | Image Slider";
	});
	window.onload = () => {
		let deleteFlag = 0;
		let deleteInterval = setInterval(() => {
			if (deleteFlag === 0) {
				try {
					// document.getElementsByClassName("filepond--credits")[0].remove();
					document.getElementsByClassName("filepond--browser")[0].setAttribute("accept", "image/png, image/jpeg, image/gif");
					deleteFlag = 1;
				} catch (error) {}
			} else {
				clearInterval(deleteInterval);
			}
		}, 500);
	};
	return (
		// image slider
		<div className="bg-[#EAEAEA] min-h-[calc(100vh-80px)] px-12 pb-5 max-sm:px-2">
			<div className="flex lg:flex-col text-[#004B95] font-inter font-bold text-title tracking-widest ml-[30px] pt-[20px]">
				<p>Image Slider</p>
			</div>
			<div className="h-max w-[900px] max-sm:w-64 max-sm:h-[100%] mt-[20px] ml-[30px] bg-white rounded-[10px] shadow shadow-shadowcolor-500/40 pb-5">
				<div className="font-poppins font-semibold text-subtitle tracking-wider pl-5 pt-[20px]">
					<p>Upload Images</p>
				</div>
				<div className="px-5 mt-2">
					{/* dropdown box */}
					<FilePond files={files} allowReorder={true} onreorderfiles={setFiles} allowMultiple={true} onupdatefiles={setFiles} labelIdle='Drag & Drop your files or <span className="filepond--label-action">Browse</span>' credits={null} />
				</div>
				<div className="flex justify-between px-10">
					<div>
						<div className="font-poppins font-medium text-[12px] text-[#004B95]">*Arrange Images According to you.</div>
						<div className="font-poppins font-medium text-[12px] text-[#004B95]">
							*Size for New Images must be atleast 1920 X 1080 <br></br>(must be in aspect ratio 16:9)
						</div>
						<div className="font-poppins font-medium text-[12px] text-[#004B95]">*If Images are not updated then just press control + shift + R</div>
					</div>

					<button
						onClick={() => {
							let data = new FormData();
							let images = files;
							for (let i = 0; i < images.length; i++) {
								data.append("images", images[i].file);
							}
							axios
								.post(process.env.REACT_APP_SERVER + "/api/imageSlider/", data, {
									headers: {
										"Content-Type": "multipart/form-data",
									},
								})
								.then((res) => {
									alert("Images Updated Successfully");
								});
						}}
						className="bg-kijeka-blue hover:bg-[#37A945] h-10 text-white font-medium text-description p-2 rounded-lg cursor-pointer transition-all duration-300"
					>
						Update
					</button>
				</div>
			</div>
		</div>
	);
};

export default ImageSlider;
