import React, { useState, useEffect } from "react";
import Goback from "../Drafts/Goback";
import DropDown from "../DropDown";
import DeleteCard from "./DeleteCard";
import axios from "axios";
const Delete = () => {
	const [deleteData, setDeleteData] = useState([]);

	useEffect(() => {
		axios.get(process.env.REACT_APP_SERVER + "/api/deletedBlogs/").then((res) => {
			let data = res.data.data;
			setDeleteData(data);
		});
	}, []);

	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["Delete", "/dashboard/blog/delete"],
				]}
			/>
			<div className="px-12">
				<div className="flex justify-between items-center px-4 mb-10">{deleteData.length > 0 ? <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">All Deleted Blogs</p> : <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer">No Deleted Blogs</p>}</div>
				{/* render all cards */}
				{deleteData.length > 0 ? (
					<div className="grid grid-cols-2 mt-[21px] gap-[51px] gap-y-6 pb-10">
						{deleteData.map((item, index) => {
							return <DeleteCard key={index} id={"delete-" + item["id"]} data={item} />;
						})}
					</div>
				) : (
					<></>
				)}
			</div>
		</>
	);
};

export default Delete;
