import React from "react";

const Login = () => {
	return (
		<div className="w-full min-w-screen h-full bg-[#E8E8E8] flex flex-col items-center justify-center fixed top-0 left-0 z-50 px-5 lg:px-0">
			<div>
				<a href="/dashboard">
					<img src="/static/images/logo-color.png" alt="" className="h-10 sm:h-20 w-auto object-cover md:h-full md:w-40 cursor-pointer" />
				</a>
			</div>
			<form action="/api/login/" method="post" className="bg-white p-5 lg:w-[35%] md:w-[60%] w-full my-5 rounded-lg shadow-[0px_2px_20px_rgba(166,166,166,0.25)]">
				<h1 className="text-kijeka-blue font-bold tracking-[1px] text-lg text-center">Login</h1>
				<div className="my-3">
					<p className="font-medium">Username : </p>
					<input onChange={()=>{
						localStorage.setItem("kijekaUserName", document.getElementById("username").value);
					}} type="username" id="username" name="username" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300" placeholder="Eg. AbcXyz" title="AbcXyz" required />
				</div>
				<div className="my-3">
					<p className="font-medium">Password : </p>
					<input type="password" id="password" name="password" className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full transition-all duration-300" placeholder="Eg. admin@123" pattern="(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{8,}" title="Must contain at least one number and one uppercase and lowercase letter, and at least 8 or more characters" required />
				</div>
				<div className="flex justify-center">
					<button
						type="submit"
						className="bg-kijeka-blue hover:bg-[#37A945] text-white px-10 py-2 rounded-lg transition-all duration-300"
					>
						Login
					</button>
				</div>
			</form>
		</div>
	);
};

export default Login;
