import React from "react";
import { useNavigate } from "react-router-dom";
import { BsArrowRight } from "react-icons/bs";

const Goback = ({ path }) => {
	const navigate = useNavigate();
	return (
		<div className="flex items-center justify-between px-5 sm:px-12">
			{/* navigation hierarchy */}
			<div className="cursor-pointer flex justify-start gap-x-5 py-10 items-center text-[#004B95] font-poppins font-semibold not-italic text-description tracking-[10%]" onClick={() => navigate(-1)}>
				<svg width="15" height="9" viewBox="0 0 15 9" fill="none" className="rotate-90">
					<path d="M0.513105 0.680097C0.919901 0.273301 1.57945 0.273301 1.98624 0.680097L7.49968 6.19353L13.0131 0.680097C13.4199 0.2733 14.0794 0.2733 14.4862 0.680097C14.893 1.08689 14.893 1.74644 14.4862 2.15324L8.23625 8.40324C7.82945 8.81003 7.1699 8.81003 6.76311 8.40324L0.513105 2.15324C0.106309 1.74644 0.106309 1.08689 0.513105 0.680097Z" fill="#004B95" />
				</svg>
				<p>Go back</p>
				{path.map((item, index) => {
					return (
						<div key={index} className="flex flex-nowrap gap-3">
							<BsArrowRight />
							<a href={item[1]} className=" text-[#004B95] font-poppins font-semibold not-italic text-description leading-[14.52px] tracking-[10%]">
								{item[0]}
							</a>
						</div>
					);
				})}
			</div>

			{!window.location.pathname.toString().includes("/dashboard/blog/newblog") ? (
				<a href="/dashboard/blog/newblog">
					<div className="flex items-center gap-3 hover:shadow-[0px_2px_20px_rgba(166,166,166,0.25)] p-5 rounded-lg transition-all duration-300 cursor-pointer">
						<svg width="20" height="20" viewBox="0 0 46 46" fill="none" stroke="#37A945">
							<path d="M21.3802 1.91309H13.1354C6.35487 1.91309 2.10352 6.7135 2.10352 13.5095V31.8424C2.10352 38.6384 6.33503 43.4388 13.1354 43.4388H32.5929C39.3955 43.4388 43.627 38.6384 43.627 31.8424V22.9604" stroke="#004B95" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" />
							<path fillRule="evenodd" clipRule="evenodd" d="M15.505 19.8446L31.9834 3.36615C34.0363 1.31545 37.3637 1.31545 39.4166 3.36615L42.1002 6.04971C44.1531 8.10263 44.1531 11.4323 42.1002 13.483L25.5424 30.0408C24.6449 30.9382 23.4277 31.4432 22.1576 31.4432H13.8975L14.1047 23.1081C14.1356 21.8821 14.6362 20.7134 15.505 19.8446Z" stroke="#004B95" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" />
							<path d="M29.4795 5.91211L39.5478 15.9804" stroke="#004B95" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round" />
						</svg>
						<p className="font-semibold text-[18px] tracking-[5%] text-[#004B95] font-poppins">Write New Blog</p>
					</div>
				</a>
			) : (
				<></>
			)}
		</div>
	);
};

export default Goback;
