import React, { useEffect, useMemo, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import { AiOutlineCloseCircle } from "react-icons/ai";
import classNames from "classnames";
import { dashboardTopLink } from "../../lib/constants";
import { linkClass, activeLinkClass, bottomLinkClass } from "../../lib/constants/classes";

const Sidebar = ({ setSidebarOpen, sidebarOpen }) => {
  const location = useLocation();

  // Normalize role
  const role = useMemo(() => {
    const raw = localStorage.getItem("role") || "";
    return raw.replaceAll('"', "").trim().toLowerCase();
  }, []);

  // Active menu from path
  const [activeMenu, setActiveMenu] = useState("/dashboard/home");

  useEffect(() => {
    const p = location.pathname;
    if (p === "/dashboard/home") setActiveMenu("/dashboard/home");
    else if (p === "/dashboard/blog" || p.includes("/blog")) setActiveMenu("/dashboard/blog");
    else if (["/dashboard/add-products","/dashboard/hot-products","/dashboard/all-products"].includes(p))
      setActiveMenu("/dashboard/add-products");
    else if (p === "/dashboard/imageSlider") setActiveMenu("/dashboard/imageSlider");
    else if (p === "/dashboard/youtubevideos") setActiveMenu("/dashboard/youtubevideos");
    else if (p === "/dashboard/clientlogos") setActiveMenu("/dashboard/clientlogos");
    else if (p === "/dashboard/reachusform") setActiveMenu("/dashboard/reachusform"); // fixed typo
    else if (p === "/dashboard/contactdetails") setActiveMenu("/dashboard/contactdetails");
    else if (p === "/dashboard/careers") setActiveMenu("/dashboard/careers");
    else if (p === "/dashboard/users") setActiveMenu("/dashboard/users");
    else setActiveMenu("/dashboard/home");
  }, [location.pathname]);

  return (
    <div className={`fixed top-0 h-full bg-sidebar w-screen sm:w-[20%] z-50 sm:z-0 transition-all duration-300 ${sidebarOpen ? "" : "-translate-x-[100%] sm:-translate-x-0"}`}>
      <div className="flex items-center justify-end w-screen pr-5 mt-4">
        <button onClick={() => setSidebarOpen(false)} className="lg:hidden xl:hidden outline-none text-white sm:block" aria-hidden="true">
          <AiOutlineCloseCircle fontSize={30} />
        </button>
      </div>

      <div className="flex-1 mt-20 max-h-[calc(100%-25%)] overflow-y-scroll no-scrollbar">
        {dashboardTopLink.map((item, index) => {
          const roles = item.role.map(r => r.toLowerCase());
          if (!roles.includes(role)) return null;

          return (
            <div key={index} className="text-white text-xl ml-6 my-4 py-2">
              <Link
                onClick={() => {
                  setActiveMenu(item.path);
                  setSidebarOpen(false);
                }}
                to={item.path}
                className={classNames(activeMenu === item.path ? activeLinkClass : "text-white", linkClass, "transition-all duration-300")}
              >
                {item.label}
                {activeMenu === item.path && (
                  <svg xmlns="http://www.w3.org/2000/svg" width="13" height="20" viewBox="0 0 13 20" fill="none" className="inline ml-2">
                    <path d="M1.16493 19.5016C0.611689 18.9483 0.611689 18.0513 1.16493 17.4981L8.6632 9.99984L1.16493 2.50157C0.611688 1.94833 0.611688 1.05134 1.16493 0.498102C1.71817 -0.0551415 2.61516 -0.0551415 3.1684 0.498102L11.6684 8.9981C12.2216 9.55134 12.2216 10.4483 11.6684 11.0016L3.1684 19.5016C2.61516 20.0548 1.71817 20.0548 1.16493 19.5016Z" fill="white" />
                  </svg>
                )}
              </Link>
            </div>
          );
        })}
      </div>

      <div className="flex justify-center items-center">
        <div className={bottomLinkClass + " text-xl my-4 py-2"}>
          <a href="/api/logout/" className="flex gap-x-4 px-5 items-center justify-center font-semibold">
            Log Out
          </a>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;
