import React, { useEffect, useState } from "react";
import Inquires from "./dash_components/Inquires";
import PieComp from "./dash_components/PieComp";
import { dashboardMainClass } from "../../lib/constants/classes";
import JobInquires from "./dash_components/JobInquires";
import axios from "axios";
import DownloadData from "../DownloadData/DownloadData";

const Dashboard = () => {
	const [inquiresData, setInquiresData] = useState([]);
	const [conatctData, setConatctData] = useState([]);
	// use to display title and header title
	useEffect(() => {
		document.title = "Kijeka | Home";
		axios
			.get(process.env.REACT_APP_SERVER + "/api/inquryData?user="+localStorage.getItem("kijekaUserName"))
			.then((res) => {
				setInquiresData(res.data.data);
				localStorage.setItem("role", res.data.role);
			})
			.catch((err) => {
				console.log(err);
			});
		axios
			.get(process.env.REACT_APP_SERVER + "/api/contactData?user="+localStorage.getItem("kijekaUserName"))
			.then((res) => {
				setConatctData(res.data.data);
			})
			.catch((err) => {
				console.log(err);
			});
	}, []);
	return (
		<div className="bg-[#EAEAEA] min-h-[calc(100vh-80px)] relative pb-6 transition-all duration-300">
			<DownloadData dataInquiry={inquiresData} dataContact={conatctData} />
			<div className="flex items-center justify-between px-12 py-4 mb-0">
				<p className="text-kijeka-blue font-bold text-title">Home</p>
				<div
					className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description p-2 rounded-lg cursor-pointer transition-all duration-300"
					onClick={() => {
						document.getElementById("DownloadDataOverlay").classList.remove("scale-0");
						document.getElementById("DownloadDataOverlay").classList.remove("opacity-0");
					}}
				>
					<p>Download Data</p>
				</div>
			</div>
			<div className="flex flex-col md:flex-row gap-3 md:items-center md:justify-between px-12 transition-all duration-300">{localStorage.getItem("role") === "admin" || localStorage.getItem("role") === "blog" ? <iframe className="rounded-lg overflow-hidden" src="https://lookerstudio.google.com/embed/reporting/5ab23700-93bc-43d9-bb47-4cf0595e0694/page/6zXD" frameborder="0" style={{ border: 0, width: "100%", height: "650px" }} allowfullscreen></iframe> : () => {}}</div>
			{localStorage.getItem("role") === "admin" || localStorage.getItem("role") === "inquiry" ? (
				<div className={dashboardMainClass}>
					{/* This components are display to data on dashboard form ./dash_components/ */}
					<Inquires inquiresData={inquiresData} />
					<JobInquires conatctData={conatctData} />
					{/* <Graph /> */}
				</div>
			) : (
				() => {}
			)}
		</div>
	);
};

export default Dashboard;
