import React, { useState } from "react";
import { ExportToCsv } from "export-to-csv";

const DownloadData = ({ dataInquiry, dataContact }) => {
	const [isRecentDropdownSelected, setIsRecentDropdownSelected] = useState("Recent");

	var data = [
		{
			name: "Test 1",
			age: 13,
			average: 8.2,
			approved: true,
			description: "using 'Content here, content here' ",
		},
		{
			name: "Test 2",
			age: 11,
			average: 8.2,
			approved: true,
			description: "using 'Content here, content here' ",
		},
		{
			name: "Test 4",
			age: 10,
			average: 8.2,
			approved: true,
			description: "using 'Content here, content here' ",
		},
	];

	const options = {
		fieldSeparator: ",",
		filename: "Kijeka Data",
		quoteStrings: '"',
		decimalSeparator: ".",
		useTextFile: false,
		useBom: true,
		showLabels: true,
		useKeysAsHeaders: false,
		headers: ["Id", "Name", "Email", "Phone No", "Country", "Company Name", "Query", "Address", "Suscribed ?", "Inquiry ?"],
	};

	const csvExporter = new ExportToCsv(options);

	return (
		<div className="w-full h-full bg-black/50 z-50 fixed top-0 left-0 scale-0 opacity-0 flex items-center justify-center transition-all duration-300" id="DownloadDataOverlay">
			<div className="w-1/2 max-w-[800px] bg-white flex flex-col items-center rounded-lg p-4">
				<h1 className="text-kijeka-blue font-bold text-xl">Download Data</h1>
				<div className="w-full">
					<div className="my-4 grid grid-flow-col grid-rows-3 gap-4">
						{/* <div className="bg-white shadow-[0px_2px_20px_rgba(166,166,166,0.25)] p-3 rounded-lg flex flex-col items-end justify-end">
							<input id="isWebsiteViewsSelected" name="isWebsiteViewsSelected" aria-describedby="checkbox-1" type="checkbox" className="bg-gray-50 border-gray-300 focus:ring-3 focus:ring-blue-300 h-4 w-4" />
							<div className="flex items-center gap-3 w-full">
								<p className="text-kijeka-blue font-bold">1.</p>
								<p className="text-kijeka-blue font-semibold">Website Views</p>
							</div>
						</div> */}
						<div className="bg-white shadow-[0px_2px_20px_rgba(166,166,166,0.25)] p-3 rounded-lg flex flex-col items-end justify-end">
							<input id="isInquiriesSelected" name="isInquiriesSelected" aria-describedby="checkbox-1" type="checkbox" className="bg-gray-50 border-gray-300 focus:ring-3 focus:ring-blue-300 h-4 w-4" />
							<div className="flex items-center gap-3 w-full">
								<p className="text-kijeka-blue font-bold">1.</p>
								<p className="text-kijeka-blue font-semibold">Inquiries</p>
							</div>
						</div>
						<div className="bg-white shadow-[0px_2px_20px_rgba(166,166,166,0.25)] p-3 rounded-lg flex flex-col items-end justify-end">
							<input id="isJobInquiriesSelected" name="isJobInquiriesSelected" aria-describedby="checkbox-1" type="checkbox" className="bg-gray-50 border-gray-300 focus:ring-3 focus:ring-blue-300 h-4 w-4" />
							<div className="flex items-center gap-3 w-full">
								<p className="text-kijeka-blue font-bold">2.</p>
								<p className="text-kijeka-blue font-semibold">Job Inquiries</p>
							</div>
						</div>
					</div>
					<div className="w-full">
						<div className="flex items-center justify-end gap-4">
							<div
								className="px-9 py-1 text-[#808080] bg-[#A6A6A64D] rounded-lg cursor-pointer hover:bg-[#F21818] hover:text-white transition-all duration-300"
								onClick={() => {
									document.getElementById("DownloadDataOverlay").classList.add("scale-0");
									document.getElementById("DownloadDataOverlay").classList.add("opacity-0");
									document.getElementById("isSelectAllFromDownloadData").checked = false;
									document.getElementById("isWebsiteViewsSelected").checked = false;
									document.getElementById("isBlogsViews&LikesSelected").checked = false;
									document.getElementById("isBlogInquiriesSelected").checked = false;
									document.getElementById("isInquiriesSelected").checked = false;
									document.getElementById("isJobInquiriesSelected").checked = false;
								}}
							>
								Cancel
							</div>
							<div
								className="px-5 py-1 text-white bg-kijeka-blue rounded-lg cursor-pointer hover:bg-[#37A945] transition-all duration-300"
								onClick={() => {
									if (document.getElementById("isInquiriesSelected").checked || document.getElementById("isJobInquiriesSelected").checked) {
										if (document.getElementById("isJobInquiriesSelected").checked && document.getElementById("isInquiriesSelected").checked) {
											csvExporter.generateCsv(dataInquiry.concat(dataContact));
										} else if (document.getElementById("isInquiriesSelected").checked) {
											csvExporter.generateCsv(dataInquiry);
										} else if (document.getElementById("isJobInquiriesSelected").checked) {
											csvExporter.generateCsv(dataContact);
										} else {
											alert("No Data found");
										}
									} else {
										alert("Please select any field");
									}
								}}
							>
								Download Now
							</div>
						</div>
					</div>
				</div>
			</div>
		</div>
	);
};

export default DownloadData;
