import React, { useState } from "react";
import axios from "axios";
import { FilePond, registerPlugin } from "react-filepond";
import "filepond/dist/filepond.min.css";
import FilePondPluginImageExifOrientation from "filepond-plugin-image-exif-orientation";
import FilePondPluginImagePreview from "filepond-plugin-image-preview";
import "filepond-plugin-image-preview/dist/filepond-plugin-image-preview.css";

registerPlugin(FilePondPluginImageExifOrientation, FilePondPluginImagePreview);

const ClientLogo = () => {
	const [clientLogo, setClientLogo] = useState([]);
	const [files, setFiles] = React.useState([]);

	if (clientLogo.length === 0) {
		axios.get(process.env.REACT_APP_SERVER + "/api/clientList/").then((res) => {
			let data = res.data.data;
			setClientLogo(data);
		});
	}
	// use to display title and header title
	React.useEffect(() => {
		document.title = "Kijeka | Client Logos";
	});

	return (
		<>
			{/* client logos components */}
			<div className="bg-[#EAEAEA] min-h-[calc(100vh-80px)] px-12 pb-5">
				<div className="flex lg:flex-col text-[#004B95] font-inter font-bold text-title tracking-widest ml-[30px] pt-[20px]">
					<p>Client Logos</p>
				</div>
				<div className="k sm:flex overflow-x-hidden sm:justify-between">
					<div className="l sm:border-2 sm:rounded-2xl sm:bg-white sm:shadow-inner sm:flex sm:m-5 w-full p-10">
						<div className="flex items-start gap-5 w-full">
							<div className="flex flex-col md:w-[50%] w-full">
								<div className="w-full">
									<h2 className="font-semibold pt-2 max-sm:mt-8 text-subtitle mt-2">Enter Client Name</h2>
									<input id="name" className="outline-none max-sm:w-72 w-full px-5 h-10 mt-2 border-2  rounded-lg text-sm my-3 " type="text" placeholder="Client Name" />
								</div>
								<div className="w-full">
									<h2 className="font-semibold text-subtitle my-2">Client website Link</h2>
									<input id="link" className="outline-none w-full px-5 max-sm:w-72 h-11 mt-2 border-2  rounded-lg text-sm my-1 " type="text" placeholder="Link" />
									<input id="clId" hidden />
								</div>
								<div className="w-full my-4">
									<FilePond files={files} maxFiles={1} allowReorder={true} onreorderfiles={setFiles} allowMultiple={true} onupdatefiles={setFiles} labelIdle='Drag & Drop one logo or <span className="filepond--label-action">Browse</span>' credits={null} />
								</div>
								<div className="m max-sm:pl-2 mt-6 max-sm:justify-center max-sm:flex">
									<div className="flex items-center justify-start mb-2 gap-x-2">
										<div>
											<button
												onClick={() => {
													let name = document.getElementById("name");
													let link = document.getElementById("link");
													let clId = document.getElementById("clId");
													name.value = "";
													link.value = "";
													clId.value = "";
													setFiles([]);
												}}
												className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
											>
												Cancel
											</button>
										</div>
										<div>
											<button
												onClick={() => {
													let name = document.getElementById("name");
													let link = document.getElementById("link");
													let clId = document.getElementById("clId");
													if (name.value === "" || link.value === "" || files.length === 0) {
														alert("Please fill all the fields");
													} else {
														let formdata = new FormData();
														formdata.append("name", name.value);
														formdata.append("link", link.value);
														formdata.append("clId", clId.value);
														formdata.append("logo", files[0].file);
														axios
															.post(process.env.REACT_APP_SERVER + "/api/clientList/", formdata, {
																headers: {
																	"Content-Type": "multipart/form-data",
																},
															})
															.then((res) => {
																if (res.data.hasOwnProperty("msg")) {
																	let data = res.data.data;
																	setClientLogo(data);
																	name.value = "";
																	link.value = "";
																	clId.value = "";
																	setFiles([]);
																}
																alert(res["data"]["msg"]);
															})
															.catch((error) => console.log(error));
													}
												}}
												className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
											>
												Upload
											</button>
										</div>
									</div>
								</div>
							</div>
							<div className="md:w-[50%] w-full">
								<h1 className="text-kijeka-blue font-bold text-base">Uploaded Logos</h1>
								<div className="max-h-[300px] overflow-y-scroll no-scrollbar">
									{clientLogo.map((item, index) => {
										return (
											<div key={index} id={"cl-" + item[0]} className="ytList flex items-center justify-between w-full bg-white px-4 py-3 rounded-lg shadow-md border border-[#EBEBEB] my-2 transition-all duration-300">
												<div className="flex items-center gap-4 max-w-[65%]">
													<img src={process.env.REACT_APP_SERVER + item[1]} className="w-20 h-8 object-contain" />
													<p className="text-sm font-medium text-kijeka-blue truncate">{item[0]}</p>
												</div>
												<div className="flex items-center gap-4">
													<svg
														onClick={() => {
															let name = document.getElementById("name");
															let link = document.getElementById("link");
															let clId = document.getElementById("clId");
															name.value = item[0];
															link.value = item[2];
															clId.value = item[3];
															setFiles([
																{
																	source: process.env.REACT_APP_SERVER + item[1],
																},
															]);
														}}
														width="20"
														height="20"
														viewBox="0 0 19 19"
														fill="none"
														xmlns="http://www.w3.org/2000/svg"
														className="cursor-pointer"
													>
														<path d="M8.45589 1.44043H5.18427C2.49364 1.44043 0.806641 3.3453 0.806641 6.04205V13.3168C0.806641 16.0136 2.48577 17.9184 5.18427 17.9184H12.9053C15.6046 17.9184 17.2838 16.0136 17.2838 13.3168V9.7923" stroke="#004B95" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
														<path fillRule="evenodd" clipRule="evenodd" d="M6.12469 8.55544L12.6636 2.01656C13.4782 1.20281 14.7986 1.20281 15.6132 2.01656L16.6781 3.08144C17.4927 3.89606 17.4927 5.21731 16.6781 6.03106L10.1077 12.6014C9.75157 12.9576 9.26857 13.1579 8.76457 13.1579H5.48682L5.56907 9.85044C5.58132 9.36394 5.77994 8.90019 6.12469 8.55544Z" stroke="#004B95" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
														<path d="M11.6694 3.02637L15.6647 7.02162" stroke="#004B95" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
													</svg>
													<p
														onClick={() => {
															axios.delete(process.env.REACT_APP_SERVER + "/api/clientList/?clientId=" + item[3]).then((res) => {
																let cl = document.getElementById("cl-" + item[0]);
																cl.classList.add("-translate-x-full");
																setTimeout(() => {
																	cl.remove();
																	let ytList = document.getElementsByClassName("ytList");
																	for (let i = 0; i < ytList.length; i++) {
																		ytList[i].getElementsByClassName("ytListIndex")[0].innerText = i + 1 + ".";
																	}
																}, 300);
															});
														}}
														className="bg-[#D9D9D9] px-2 py-1 text-gray-400 text-xs font-semibold rounded-full hover:bg-red-500 hover:text-white cursor-pointer transition-all duration-300"
													>
														Remove
													</p>
												</div>
											</div>
										);
									})}
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		</>
	);
};

export default ClientLogo;
