import React, { useState, useEffect } from "react";
import Goback from "../Drafts/Goback";

import DropDown from "../DropDown";
import Reviewcard1 from "./Reviewcard1";
import axios from "axios";

const ReviewBlog = () => {
	const [reviewsData, setReviewsData] = useState([]);

	useEffect(() => {
		axios.get(process.env.REACT_APP_SERVER + "/api/underReviewBlogs/").then((res) => {
			let data = res.data.data;
			setReviewsData(data);
		});
	}, []);

	return (
		<>
			{/* {top navigation hierarchy} */}
			<Goback
				path={[
					["Blogs", "/dashboard/blog"],
					["Review Blog", "/dashboard/blog/reviewblog"],
				]}
			/>
			<div className="px-12">
				<div className="flex justify-between items-center px-4 mb-10">{reviewsData.length > 0 ? <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer  ">All Under Review Blogs</p> : <p className="font-bold text-[20px] leading-[30px] tracking-[10%] text-[#004B95] font-poppins cursor-pointer  ">No Under Review Blogs</p>}</div>
				{reviewsData.length > 0 ? (
					<div className="grid grid-cols-2 mt-[21px] gap-[51px] gap-y-6 pb-10">
						{/* render all blog cards */}
						{reviewsData.map((item, index) => {
							return <Reviewcard1 key={index} id={"review-" + item["id"]} data={item} />;
						})}
					</div>
				) : (
					<></>
				)}
			</div>
		</>
	);
};

export default ReviewBlog;
