import React from 'react'

const TabNavItem = ({ id, title, activeTab, setActiveTab }) => {

     const handleClick = () => {
          setActiveTab(id);
     };

     return (
          <li onClick={handleClick} className={"py-4 md:px-8 px-4 text-subtitle cursor-pointer transition-all duration-300 " + (activeTab === id ? "bg-white text-kijeka-blue font-semibold" : "bg-whiteBG")}>
               {title}
          </li>
     )
}

export default TabNavItem