import { Routes, Route } from "react-router-dom";
import React, { useState } from "react";
//Components
import AddProducts from "./Pages/AddProducts";
import AllProducts from "./Pages/AllProducts";
import HotProducts from "./Pages/HotProducts";

import Dashboard from "./Components/Dashboard/Dashboard";
import Sidebar from "./Components/shared/Sidebar.jsx";
import Header from "./Components/shared/Header.jsx";
import Yt from "./Components/YoutubeVideos/Yt";
import Review from "./Components/Review/Review";
import Form from "./Components/ReachUs/Form";
import Contact from "./Components/Contact/Contact";
import ImageSlider from "./Components/ImageSlider/ImageSlider";
import ClientLogo from "./Components/ClientLogo/ClientLogo";
import NewBlog from "./Components/Blog/CrudBlogs/NewBlogs/NewBlog";
import ReviewBlog from "./Components/Blog/CrudBlogs/UnderReview/ReviewBlog";
import Published from "./Components/Blog/CrudBlogs/Publish/Published";
import Rejected from "./Components/Blog/CrudBlogs/Reject/Rejected";
import Delete from "./Components/Blog/CrudBlogs/Deleted/Delete";
import Approved from "./Components/Blog/CrudBlogs/Approves/Approved";
import BlogMain from "./Components/Blog/CrudBlogs/BlogMain";
import Drafts from "./Components/Blog/CrudBlogs/Drafts/Drafts";
import DownloadData from "./Components/DownloadData/DownloadData";
import Job1 from "./Pages/Job1";
import Login from "./Components/Login/Login";
import Users from "./Pages/Users";

function App() {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  return (
    <div className="flex flex-row bg-natural-900 h-full w-full relative overflow-x-hidden">
      <Sidebar setSidebarOpen={setSidebarOpen} sidebarOpen={sidebarOpen} />
      <Header setSidebarOpen={setSidebarOpen} />
      {/* <DownloadData /> */}
      <div className="flex-1 pl-0 lg:pl-[20%]">
        <div className="bg-white flex sm:flex-row sm:justify-between items-center w-full sm:w-full shadow-lg h-max px-10 mb-20 z-50"></div>
        <Routes>
          <Route path="dashboard">
            <Route path="home" element={<Dashboard title="Home" />} />
            <Route
              path="youtubevideos"
              element={<Yt title="youtube Videos" />}
            />
            {/* <Route path="review" element={<Review title="Review" />} /> */}
            <Route path="add-products" element={<AddProducts />} />
            <Route path="hot-products" element={<HotProducts />} />
            <Route path="all-products" element={<AllProducts />} />
            <Route
              path="clientlogos"
              element={<ClientLogo title="Client Logos" />}
            />
            {/* Blog Nested Routing */}
            <Route path="blog" element={<BlogMain />}>
              <Route path="newblog" element={<NewBlog />} />
              <Route path="drafts" element={<Drafts />} />
              <Route path="reviewblog" element={<ReviewBlog />} />
              <Route path="published" element={<Published />} />
              <Route path="rejected" element={<Rejected />} />
              <Route path="delete" element={<Delete />} />
            </Route>
            <Route
              path="imageSlider"
              element={<ImageSlider title="Image Slider" />}
            />
            <Route path="careers" element={<Job1 title="Careers" />} />
            <Route
              path="contactdetails"
              element={<Contact title="Contact Details" />}
            />
            <Route
              path="reachusform"
              element={<Form title="Reach us from" />}
            />
            <Route path="users" element={<Users title="Users" />} />
            <Route path="login" element={<Login />} />
          </Route>
        </Routes>
      </div>
    </div>
  );
}

export default App;
