import React, { useState } from "react";
import { HiMenu } from "react-icons/hi";
import { userBarClass, navClass, searchBarClass } from "../../lib/constants/classes";
import axios from "axios";
// import { ChevronDownIcon } from "@heroicons/react/20/solid";

const Header = ({ setSidebarOpen }) => {
	const [searchProduct, setSearchProduct] = useState([]);
	const [searchCategory, setSearchCategory] = useState([]);
	const [selectedLanguage, setSelectedLanguage] = useState("EN");
	window.onload = function () {
		const googleTranslateElementInit = () => {
			new window.google.translate.TranslateElement(
				{
					pageLanguage: "en",
					autoDisplay: true,
				},
				"google_translate_element"
			);
		};
		var addScript = document.createElement("script");
		addScript.setAttribute("src", "//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit");
		document.body.appendChild(addScript);
		window.googleTranslateElementInit = googleTranslateElementInit;
		setInterval(() => {
			try {
				document.getElementById(":1.container").style.transform = "scale(0)";
				document.getElementById(":1.container").parentElement.style.transform = "scale(0)";
				document.getElementsByTagName("body")[0].style.top = "0px";
				document.getElementById("google_translate_element").style.transform = "scale(0)";
			} catch (e) {}
		}, 500);
	};
	return (
		<div className="z-30 sm:z-50 w-0 transition-all duration-300">
			<div className="absolute top-0 left-0 scale-0 -translate-y-[400%] w-0 h-0">
				<div id="google_translate_element"></div>
			</div>
			<nav className={navClass}>
				{/* Hamburger Menu Icon */}
				<div className="lg:hidden xl:hidden">
					<button className="text-2xl text-black  outline-none" onClick={() => setSidebarOpen(true)}>
						<HiMenu />
					</button>
				</div>
				{/* End */}
				{/* Header Components */}
				<div>
					<a href="/">
						<img src="/static/images/logo-color.png" alt="" className="h-10 sm:h-20 w-auto object-cover md:h-full md:w-32 cursor-pointer" />
					</a>
				</div>
				{/* search */}
				<div className="relative group md:w-48 hidden sm:flex items-center justify-end h-10 ">
					<div id="dummyPathForSearch" className={"absolute top-0 right-0 z-0 min-w-full min-h-32 w-32 h-0"}></div>
					<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 22 22" fill="none" className="absolute top-1/2 -translate-y-1/2 right-4 group-hover:right-4 group-focus:right-4 w-4 h-4 transition-all duration-300">
						<circle cx="8.03713" cy="8.11061" r="6.76271" stroke="#004B95" strokeWidth="2" />
						<path d="M14.7998 14.8735L20.2744 20.0261" stroke="#004B95" strokeWidth="2" strokeLinecap="round" />
					</svg>
					<input
						type="text"
						placeholder="Search"
						id="navSearchBar"
						onKeyUp={() => {
							let navSearchBar = document.getElementById("navSearchBar").value;

							if (navSearchBar.length > 0) {
								document.getElementById("searchOverlay").classList.remove("scale-y-0");
								document.getElementById("searchOverlay").classList.remove("opacity-0");
								axios.get(process.env.REACT_APP_SERVER + "/api/searchDatabase/?searchQuery=" + navSearchBar).then((res) => {
									let data = res["data"]["data"];
									setSearchProduct(data["products"]);
									setSearchCategory(data["categories"]);
									setTimeout(() => {
										document.getElementById("dummyPathForSearch").style.height = document.getElementById("searchOverlay").offsetHeight + "px";
										document.getElementById("dummyPathForSearch").style.width = document.getElementById("searchOverlay").offsetWidth + "px";
									}, 300);
								});
							} else {
								document.getElementById("searchOverlay").classList.add("scale-y-0");
								document.getElementById("searchOverlay").classList.add("opacity-0");
								document.getElementById("dummyPathForSearch").style.height = 0;
								document.getElementById("dummyPathForSearch").style.width = 0;
							}
						}}
						className={"border-[0.5px] border-kijeka-blue bg-transparent z-10 outline-none rounded-lg text-sm px-3 py-1 transition-all duration-300 md:w-36 w-[100px] md:group-hover:w-48 md:focus:w-48 "}
					/>
					<div id="searchOverlay" className="absolute md:top-[38px] top-10 md:right-0 scale-y-0 opacity-0 origin-top w-max min-w-[12rem] mt-5 bg-white/90 backdrop-blur rounded-lg transition-all duration-300 shadow-lg z-50">
						{searchProduct.map((item, index) => (
							<a href={"/product/" + item[3]} key={index} className="flex items-center gap-8 px-2 py-2 border-b border-[rgba(166,166,166,0.3)] last-of-type:border-none">
								<div className="flex items-center gap-2">
									<div className="">
										<img src={process.env.REACT_APP_SERVER + "/media/images/" + item[2]} className="w-8 h-8 object-contain" alt="" />
									</div>
									<p className=" discriptionTruncate-1 text-kijeka-blue text-sm font-medium w-full">{item[0]}</p>
								</div>
							</a>
						))}
						{() => {
							if (searchProduct.length > 0) {
								return <hr />;
							}
						}}
						{searchCategory.map((item, index) => (
							<a href={item[1]} key={index} className="flex items-center w-full gap-8 px-2 py-2 border-b border-[rgba(166,166,166,0.3)] last-of-type:border-none">
								<div className="flex items-center gap-2">
									<p className="discriptionTruncate-1 text-kijeka-blue text-sm font-medium w-full">{item[0]}</p>
								</div>
							</a>
						))}
					</div>
				</div>
				{/* end */}

				<div className="flex items-center justify-end sm:justify-between gap-x-5">
					{/* Notification */}
					<div
						className="hidden sm:flex cursor-pointer"
						onClick={() => {
							document.getElementById("notificationOverlay").classList.toggle("scale-y-0");
							document.getElementById("notificationOverlay").classList.toggle("opacity-0");
						}}
						onBlur={() => {
							document.getElementById("notificationOverlay").classList.add("scale-y-0");
							document.getElementById("notificationOverlay").classList.add("opacity-0");
						}}
					>
						<svg width="20" height="23" viewBox="0 0 20 23" fill="none" xmlns="http://www.w3.org/2000/svg">
							<path d="M9.9999 6.44V9.77M10.0199 2C6.3399 2 3.3599 4.98 3.3599 8.66V10.76C3.3599 11.44 3.0799 12.46 2.7299 13.04L1.4599 15.16C0.679898 16.47 1.2199 17.93 2.6599 18.41C7.44118 20 12.6086 20 17.3899 18.41C17.7054 18.3048 17.9932 18.13 18.2321 17.8986C18.471 17.6671 18.6548 17.385 18.77 17.073C18.8852 16.761 18.9288 16.4271 18.8976 16.096C18.8665 15.7649 18.7613 15.445 18.5899 15.16L17.3199 13.04C16.9699 12.46 16.6899 11.43 16.6899 10.76V8.66C16.6799 5 13.6799 2 10.0199 2Z" stroke="#004B95" stroke-width="1.5" strokeMiterlimit="10" stroke-linecap="round" />
							<path d="M13.3299 18.8203C13.3299 20.6503 11.8299 22.1503 9.99992 22.1503C9.08992 22.1503 8.24992 21.7703 7.64992 21.1703C7.04992 20.5703 6.66992 19.7303 6.66992 18.8203" stroke="#004B95" stroke-width="1.5" strokeMiterlimit="10" />
							{/* <circle cx="15.5" cy="2.5" r="2.5" fill="#FF0000" /> */}
						</svg>
					</div>
					{/* Notification Overlay */}
					<div
						className="bg-white backdrop-blur absolute top-20 right-80 scale-y-0 opacity-0 origin-top transition-all duration-300 w-max min-w-[100px] rounded-lg"
						id="notificationOverlay"
						onMouseLeave={() => {
							document.getElementById("notificationOverlay").classList.add("scale-y-0");
							document.getElementById("notificationOverlay").classList.add("opacity-0");
						}}
					>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">No Notifications Yet</p>
						{/* <p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">This</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Is</p>
						<p className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium">Ansh</p> */}
					</div>

					{/* Admin Name */}
					<div className={userBarClass + " cursor-pointer hidden sm:flex"}>
						<img src={"/static/images/logoOnly.png"} alt="" className="w-10 h-10" />
						<span className="hidden sm:block text-kijeka-blue font-bold text-xl">{localStorage.getItem("kijekaUserName") !== undefined?localStorage.getItem("kijekaUserName"):"Admin"}</span>
					</div>

					{/* language */}
					<div className="flex items-center gap-1 relative cursor-pointer">
						<div
							className="flex items-center gap-1"
							onClick={() => {
								document.getElementById("languageOverlay").classList.toggle("scale-y-0");
								document.getElementById("languageOverlay").classList.toggle("opacity-0");
							}}
							onBlur={() => {
								document.getElementById("languageOverlay").classList.add("scale-y-0");
								document.getElementById("languageOverlay").classList.add("opacity-0");
							}}
						>
							<svg width="22" height="22" viewBox="0 0 24 22" fill="none" xmlns="http://www.w3.org/2000/svg">
								<path d="M8.9375 14.4556C9.39558 17.6218 10.4931 19.8517 11.7742 19.8517C13.0553 19.8517 14.1528 17.6218 14.6108 14.4556C13.7119 14.3439 12.7601 14.283 11.7742 14.283C10.7882 14.283 9.83642 14.3439 8.9375 14.4556Z" fill="#004B95" />
								<path d="M8.78352 9.23462C8.73446 9.85182 8.70801 10.4923 8.70801 11.151C8.70801 11.8096 8.73446 12.4501 8.78352 13.0673C9.73112 12.9524 10.7324 12.8915 11.7747 12.8915C12.817 12.8915 13.8182 12.9524 14.7658 13.0673C14.8149 12.4501 14.8413 11.8096 14.8413 11.151C14.8413 10.4923 14.8149 9.85182 14.7658 9.23462C13.8182 9.3495 12.817 9.41041 11.7747 9.41041C10.7324 9.41041 9.73112 9.3495 8.78352 9.23462Z" fill="#004B95" />
								<path d="M14.5586 19.4781C16.711 18.8852 18.5422 17.6244 19.7597 15.9604C18.8094 15.4281 17.5632 14.994 16.1234 14.7009C15.8451 16.586 15.3302 18.284 14.5586 19.4781Z" fill="#004B95" />
								<path d="M8.99013 19.4782C8.2181 18.2841 7.70366 16.5861 7.42536 14.7007C5.98556 14.9938 4.73896 15.4279 3.78906 15.9602C5.00691 17.6245 6.83771 18.8857 8.99013 19.4782Z" fill="#004B95" />
								<path d="M8.99013 2.82397C6.83771 3.41681 5.00653 4.67767 3.78906 6.34164C4.73935 6.8739 5.98556 7.308 7.42536 7.60111C7.70366 5.71609 8.21848 4.018 8.99013 2.82397Z" fill="#004B95" />
								<path d="M3.05237 14.7539C4.18512 14.1236 5.61687 13.6262 7.26482 13.305C7.20541 12.5957 7.17474 11.8728 7.17474 11.1506C7.17474 10.4284 7.20541 9.7055 7.26482 8.99653C5.61687 8.67528 4.18512 8.17757 3.05237 7.54761C2.50114 8.64569 2.19141 9.8649 2.19141 11.1506C2.19141 12.4363 2.50114 13.6555 3.05237 14.7539Z" fill="#004B95" />
								<path d="M11.7742 2.44946C10.4931 2.44946 9.39558 4.6794 8.9375 7.84557C9.83642 7.9573 10.7882 8.0182 11.7742 8.0182C12.7601 8.0182 13.7119 7.9573 14.6108 7.84557C14.1528 4.6794 13.0553 2.44946 11.7742 2.44946Z" fill="#004B95" />
								<path d="M20.4966 7.54736C19.3639 8.17768 17.9321 8.67503 16.2842 8.99628C16.3436 9.7056 16.3743 10.4285 16.3743 11.1507C16.3743 11.8729 16.3436 12.5958 16.2842 13.3047C17.9321 13.626 19.3639 14.1237 20.4966 14.7537C21.0479 13.6556 21.3576 12.4364 21.3576 11.1507C21.3576 9.86501 21.0479 8.6458 20.4966 7.54736Z" fill="#004B95" />
								<path d="M14.5586 2.82397C15.3306 4.018 15.8451 5.71609 16.1234 7.60146C17.5632 7.30835 18.8098 6.87426 19.7597 6.34199C18.5418 4.67767 16.711 3.41646 14.5586 2.82397Z" fill="#004B95" />
							</svg>
							<p className="text-kijeka-blue hidden md:block">{selectedLanguage}</p>
							<svg width="10" height="9" viewBox="0 0 11 9" fill="none" xmlns="http://www.w3.org/2000/svg" className="hidden md:block">
								<path d="M5.55998 8.76855L10.5087 0.986159H0.61127L5.55998 8.76855Z" fill="#004B95" />
							</svg>
						</div>
						{/* languageoverlay */}
						<div
							className="bg-white backdrop-blur absolute top-12 right-0 scale-y-0 opacity-0 origin-top transition-all duration-300 w-max min-w-[100px] rounded-lg"
							id="languageOverlay"
							onMouseLeave={() => {
								document.getElementById("languageOverlay").classList.add("scale-y-0");
								document.getElementById("languageOverlay").classList.add("opacity-0");
							}}
						>
							<p
								onClick={() => {
									let language = "en";
									let elementGoogle = document.getElementById("google_translate_element");
									elementGoogle.getElementsByTagName("select")[0].value = language;
									elementGoogle.getElementsByTagName("select")[0].dispatchEvent(new Event("change"));
									document.getElementById(":1.container").style.transform = "scale(0)";
									document.getElementById("google_translate_element").style.transform = "scale(0)";
									setSelectedLanguage("EN");
								}}
								className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
							>
								English
							</p>
							<p
								onClick={() => {
									let language = "fr";
									let elementGoogle = document.getElementById("google_translate_element");
									elementGoogle.getElementsByTagName("select")[0].value = language;
									elementGoogle.getElementsByTagName("select")[0].dispatchEvent(new Event("change"));
									document.getElementById(":1.container").style.transform = "scale(0)";
									document.getElementById("google_translate_element").style.transform = "scale(0)";
									setSelectedLanguage("FR");
								}}
								className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
							>
								French
							</p>

							<p
								onClick={() => {
									let language = "zh-CN";
									let elementGoogle = document.getElementById("google_translate_element");
									elementGoogle.getElementsByTagName("select")[0].value = language;
									elementGoogle.getElementsByTagName("select")[0].dispatchEvent(new Event("change"));
									document.getElementById(":1.container").style.transform = "scale(0)";
									document.getElementById("google_translate_element").style.transform = "scale(0)";
									setSelectedLanguage("CH");
								}}
								className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
							>
								Chinese
							</p>
							<p
								onClick={() => {
									let language = "ar";
									let elementGoogle = document.getElementById("google_translate_element");
									elementGoogle.getElementsByTagName("select")[0].value = language;
									elementGoogle.getElementsByTagName("select")[0].dispatchEvent(new Event("change"));
									document.getElementById(":1.container").style.transform = "scale(0)";
									document.getElementById("google_translate_element").style.transform = "scale(0)";
									setSelectedLanguage("AR");
								}}
								className="px-4 py-2 border-b border-[rgba(166,166,166,0.3)] hover:tracking-[1px] text-kijeka-blue cursor-pointer text-sm font-medium"
							>
								Arabic
							</p>
						</div>
					</div>
				</div>
				{/* End */}
			</nav>
			{/* Dummy Nav for Sticky Nav */}
			{/* <div className="bg-white flex sm:flex-row sm:justify-between items-center sm:w-[80%] shadow-lg h-fit px-10 mb-20 -z-50"></div> */}
		</div>
	);
};

export default Header;
