import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";
//Components
import TabContent from "../Components/TabContent/TabContent";
import TabNavItem from "../Components/TabNavItem/TabNavItem";
import { FilePond, registerPlugin } from "react-filepond";
import "filepond/dist/filepond.min.css";
import FilePondPluginImageExifOrientation from "filepond-plugin-image-exif-orientation";
import FilePondPluginImagePreview from "filepond-plugin-image-preview";
import "filepond-plugin-image-preview/dist/filepond-plugin-image-preview.css";
// import axios from "axios";
//Styles for text editor logic
import "../css/froala_editor.css";

const AddProducts = () => {
  //Text Editor Logic
  const javaScripts = [
    "https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/codemirror.min.js",
    "https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.3.0/mode/xml/xml.min.js",
    "/static/js/froala_editor.min.js",
    "/static/js/output.min.js",
    "/static/js/editorLoader.js",
  ];
  const [category, setCategory] = useState([]);
  const [subCategory, setSubCategory] = useState([]);
  const [loading, setLoading] = useState("hidden");
  const [files, setFiles] = React.useState([]);
  const [images, setImages] = React.useState([]);

  //   multiple image upload
  if (images.length === 0) {
    const urlParams = new URLSearchParams(window.location.search);
    const name = urlParams.get("name");
    var imageUrl = [];
    var urlname = [
      "image1_url",
      "image2_url",
      "image3_url",
      "image4_url",
      "image5_url",
      "image6_url",
      "image7_url",
      "main_img",
    ];
    axios
      .get(
        process.env.REACT_APP_SERVER +
          "/api/getProductDetail/?productName=" +
          name
      )
      .then((res) => {
        for (let i = 0; i < urlname.length; i++) {
          try {
            imageUrl[i] = res.data.data["pro_images"][urlname[i]];
          } catch (e) {
            imageUrl[i] = "";
          }
        }
        let dataImage = imageUrl;
        console.log(dataImage);
        setImages(dataImage);
        let tempArr = [];
        for (let i = 0; i < dataImage.length; i++) {
          if (dataImage[i] === "") {
            continue;
          } else {
            tempArr.push({
              source: process.env.REACT_APP_SERVER + dataImage[i],
            });
          }
        }
        setFiles(tempArr);
      });
  }

  React.useEffect(() => {
    document.title = "Kijeka | Image Slider";
  });
  useEffect(() => {
    let deleteFlag = 0;
    let deleteInterval = setInterval(() => {
      if (deleteFlag === 0) {
        try {
          // document.getElementsByClassName("filepond--credits")[0].remove();
          document
            .getElementsByClassName("filepond--browser")[0]
            .setAttribute("accept", "image/png, image/jpeg, image/gif");
          deleteFlag = 1;
        } catch (error) {}
      } else {
        clearInterval(deleteInterval);
      }
    }, 500);
  }, []);
  //   end of multiple image upload

  for (let i = 0; i < javaScripts.length; i++) {
    let element = javaScripts[i];
    let script = document.createElement("script");
    script.src = element;
    script.type = "text/javascript";
    document.body.appendChild(script);
  }
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const name = urlParams.get("name");
    if (name) {
      axios
        .get(
          process.env.REACT_APP_SERVER +
            "/api/getProductDetail/?productName=" +
            name
        )
        .then((data) => {
          document.getElementById("productName").value = name;
          document.getElementById("edit").value =
            data["data"]["data"]["description"];
          document.getElementById("category").value =
            data["data"]["data"]["category"];
          axios
            .get(
              process.env.REACT_APP_SERVER +
                "/api/subCategoryList?category=" +
                data["data"]["data"]["category"]
            )
            .then((data2) => {
              setSubCategory(data2["data"]["data"]);
              if (
                data["data"]["data"]["subCategory"] !== "" &&
                data["data"]["data"]["subCategory"] !== undefined
              ) {
                setTimeout(() => {
                  document.getElementById("subCategory").value =
                    data["data"]["data"]["subCategory"];
                }, 1000);
              }
            })
            .catch((error) => console.log(error));

          document.getElementById("modelNo").value =
            data["data"]["data"]["modelNo"] !== undefined
              ? data["data"]["data"]["modelNo"]
              : "";
          document.getElementById("isOnHome").checked =
            data["data"]["data"]["isOnHome"];
          document.getElementById("ytLink").value =
            data["data"]["data"]["ytLink"] !== undefined
              ? data["data"]["data"]["ytLink"]
              : "";

          var pdfUrl =
            process.env.REACT_APP_SERVER + data["data"]["data"]["productPdf"];

          if (
            pdfUrl !== process.env.REACT_APP_SERVER &&
            pdfUrl !== undefined &&
            data["data"]["data"]["productPdf"] !== undefined
          ) {
            fetch(pdfUrl)
              .then((response) => response.blob())
              .then((blob) => {
                const file1 = new File(
                  [blob],
                  pdfUrl.split("/media/pdf/")[1].split("_")[0].split(".")[0] +
                    ".pdf",
                  { type: blob.type }
                );
                const dataTransfer1 = new DataTransfer();
                dataTransfer1.items.add(file1);
                const fileList1 = dataTransfer1.files;
                const fileInput1 = document.getElementById("pdf");
                fileInput1.files = fileList1;
                const fileName1 = document.getElementById("pdf").files[0].name;
                document.getElementById("pdfContainer").innerHTML = fileName1;
              });
          }
        })
        .catch((error) => console.log(error));
    }
  }, []);

  if (category.length === 0) {
    axios
      .get(process.env.REACT_APP_SERVER + "/api/categoryList/")
      .then((data) => setCategory(data["data"]["data"]))
      .catch((error) => console.log(error));
  }

  const handleSubCategory = () => {
    if (document.getElementById("isSubCategory").checked) {
      document.getElementById("subCategoryName").disabled = false;
      document
        .getElementById("subCategoryName")
        .classList.remove("cursor-not-allowed");
      document
        .getElementById("subCategoryLabel")
        .classList.remove("text-gray-300");
    } else {
      document.getElementById("subCategoryName").disabled = true;
      document
        .getElementById("subCategoryName")
        .classList.add("cursor-not-allowed");
      document
        .getElementById("subCategoryLabel")
        .classList.add("text-gray-300");
    }
  };

  const [activeTab, setActiveTab] = useState("tab1");

  if (activeTab === "tab1") {
    document.title = "Kijeka | Edit Products";
    // document.getElementById("header_title").innerHTML = "Add Products";
  } else if (activeTab === "tab2") {
    document.title = "Kijeka | Edit Category";
    // document.getElementById("header_title").innerHTML = "Add Category";
  }

  return (
    <div className="w-full bg-[#EAEAEA] min-h-[calc(100vh-80px)] pb-6 md:px-12 py-4 px-4">
      <div className="">
        <p className="text-kijeka-blue font-bold text-title">Product</p>
      </div>
      <div
        className={
          "absolute top-0 right-0 z-50 origin-center w-[calc(100%-32px)] h-[calc(100%-32px)] flex items-center justify-center overflow-hidden " +
          loading
        }
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          xmlnsXlink="http://www.w3.org/1999/xlink"
          style={{
            margin: "auto",
            display: "block",
          }}
          width="200px"
          height="200px"
          viewBox="0 0 100 100"
          preserveAspectRatio="xMidYMid"
        >
          <circle
            cx={50}
            cy={50}
            fill="none"
            stroke="#004b95"
            strokeWidth={10}
            r={40}
            strokeDasharray="188.49555921538757 64.83185307179586"
          >
            <animateTransform
              attributeName="transform"
              type="rotate"
              repeatCount="indefinite"
              dur="1s"
              values="0 50 50;360 50 50"
              keyTimes="0;1"
            />
          </circle>
        </svg>
      </div>
      <div className="my-5 bg-white rounded-lg overflow-hidden shadow-[0px_2px_20px_rgba(166,166,166,0.25)]">
        <ul className="flex md:flex-row md:items-center justify-between bg-grayBG">
          <div className="flex items-center">
            <TabNavItem
              title="Add Product"
              id="tab1"
              activeTab={activeTab}
              setActiveTab={setActiveTab}
            />
            <TabNavItem
              title="Add Category"
              id="tab2"
              activeTab={activeTab}
              setActiveTab={setActiveTab}
            />
          </div>
          <Link to={`/dashboard/all-products`}>
            <p className="md:px-5 hidden md:block px-2 text-description font-semibold text-[#37A945] underline">
              Edit/View All Uploaded Products
            </p>
          </Link>
        </ul>
        <div>
          <TabContent id="tab1" activeTab={activeTab}>
            <div className="md:p-5 px-5">
              <Link to={`/dashboard/all-products`}>
                <p className="md:px-5 md:hidden block mb-4 text-description font-semibold text-[#37A945] underline">
                  View All Uploaded Products
                </p>
              </Link>
              <div className="flex items-center flex-col md:flex-row gap-10">
                <div className="w-full">
                  <p className="font-medium">Name of Product</p>
                  <input
                    type="text"
                    id="productName"
                    name="productName"
                    className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300"
                    placeholder="Product name"
                  />
                </div>
                <div className="w-full">
                  <p className="font-medium">Select category</p>
                  <select
                    name="category"
                    id="category"
                    onChangeCapture={(event) => {
                      axios
                        .get(
                          process.env.REACT_APP_SERVER +
                            "/api/subCategoryList?category=" +
                            event.target.value
                        )
                        .then((data) => setSubCategory(data["data"]["data"]))
                        .catch((error) => console.log(error));
                    }}
                    className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300"
                  >
                    <option value="" selected disabled>
                      Select Category
                    </option>
                    {category.map((item, index) => {
                      return (
                        <option key={index} value={item}>
                          {item}
                        </option>
                      );
                    })}
                  </select>
                </div>
                {subCategory.length > 0 && (
                  <div className="w-full">
                    <p className="font-medium">Select Sub Category</p>
                    <select
                      name="subCategory"
                      id="subCategory"
                      className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300"
                    >
                      <option value="" selected disabled>
                        Select Sub Category
                      </option>
                      {subCategory.map((item, index) => {
                        return (
                          <option key={index} value={item}>
                            {item}
                          </option>
                        );
                      })}
                    </select>
                  </div>
                )}

                <div className="w-full">
                  <p className="font-medium">Model No.</p>
                  <input
                    type="text"
                    id="modelNo"
                    name="modelNo"
                    className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300"
                    placeholder="Model No."
                  />
                </div>
                <div className="w-full">
                  <p className="font-medium">Upload Images</p>
                  {/* <div className="relative text-sm bg-grayBG2 hover:bg-[#37A945] px-3 py-1 mt-2 w-fit text-center text-white rounded-full transition-all duration-300 cursor-pointer">
                    <p id="imageContainer" className="cursor-pointer">
                      Choose
                    </p>
                    <input
                      required
                      type="file"
                      onInputCapture={() => {
                        let imageInput = document.getElementById("images");
                        imageInput.addEventListener("change", () => {
                          if (imageInput.files.length > 0) {
                            const fileName =
                              document.getElementById("images").files[0].name;
                            document.getElementById(
                              "imageContainer"
                            ).innerHTML = fileName;
                          }
                        });
                      }}
                      id="images"
                      name="images"
                      className="h-full w-full max-w-[50px] opacity-0 absolute top-0 left-0"
                      accept=".jpg,.jpeg,.png"
                    ></input>
                  </div> */}
                  <div className="mt-2">
                    {/* dropdown box */}
                    <FilePond
                      files={files}
                      allowReorder={true}
                      onreorderfiles={setFiles}
                      allowMultiple={true}
                      onupdatefiles={setFiles}
                      labelIdle='Drag & Drop your files or <span className="filepond--label-action">Browse</span>'
                      credits={null}
                      maxFiles={8}
                    />
                  </div>
                  <div className="">
                    <div>
                      <div className="font-poppins font-medium text-[12px] text-[#004B95]">
                        *Allow only 8 photos
                      </div>
                      <div className="font-poppins font-medium text-[12px] text-[#004B95]">
                        *put the best image of product first in image list
                      </div>
                      <div className="font-poppins font-medium text-[12px] text-[#004B95]">
                        *Size for New Images must be atleast 1920 X 1080{" "}
                        <br></br>(must be in aspect ratio 16:9)
                      </div>
                      <div className="font-poppins font-medium text-[12px] text-[#004B95]">
                        *If Images are not updated then just press control +
                        shift + R
                      </div>
                    </div>

                    {/* <button
                      onClick={() => {
                        let data = new FormData();
                        let images = files;
                        for (let i = 0; i < images.length; i++) {
                          data.append("images", images[i].file);
                        }
                        axios
                          .post(
                            process.env.REACT_APP_SERVER + "/api/imageSlider/",
                            data,
                            {
                              headers: {
                                "Content-Type": "multipart/form-data",
                              },
                            }
                          )
                          .then((res) => {
                            alert("Images Updated Successfully");
                          });
                      }}
                      className="bg-kijeka-blue hover:bg-[#37A945] h-10 text-white font-medium text-description p-2 rounded-lg cursor-pointer transition-all duration-300"
                    >
                      Update
                    </button> */}
                  </div>
                </div>
              </div>
              <div className="my-5 flex items-start gap-10 flex-col md:flex-row">
                <div className="">
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="font-medium">Upload PDF</p>
                      <div className="relative text-sm bg-grayBG2 hover:bg-[#37A945] px-3 py-1 mt-2 w-fit text-center text-white rounded-full transition-all duration-300 cursor-pointer">
                        <p id="pdfContainer" className="cursor-pointer">
                          Choose
                        </p>
                        <input
                          required
                          type="file"
                          onInputCapture={() => {
                            let imageInput = document.getElementById("pdf");
                            imageInput.addEventListener("change", () => {
                              if (imageInput.files.length > 0) {
                                const fileName =
                                  document.getElementById("pdf").files[0].name;
                                document.getElementById(
                                  "pdfContainer"
                                ).innerHTML = fileName;
                              }
                            });
                          }}
                          id="pdf"
                          name="pdf"
                          className="h-full w-full max-w-[50px] opacity-0 absolute top-0 left-0"
                          accept=".pdf"
                        ></input>
                      </div>
                    </div>
                    <div className="">
                      <p className="font-medium">Youtube Video Link</p>
                      <input
                        type="text"
                        id="ytLink"
                        name="ytLink"
                        className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue w-full md:w-64 transition-all duration-300"
                        placeholder="Youtube Video Link"
                      />
                    </div>
                  </div>
                  <div className="flex items-center mt-3 gap-3">
                    <input
                      id="isOnHome"
                      name="isOnHome"
                      aria-describedby="checkbox-1"
                      type="checkbox"
                      className="bg-gray-50 border-gray-300 focus:ring-3 focus:ring-blue-300 h-4 w-4 rounded"
                    />
                    <label
                      htmlFor="isOnHome"
                      className="font-normal text-kijeka-blue"
                    >
                      Add this product on Home Page Hot product section
                    </label>
                  </div>
                </div>
                <div className="max-md:w-full max-md:my-4">
                  <p className="font-medium">Upload Excel Sheet</p>
                  <div className="flex flex-row flex-nowrap gap-2">
                    <div className="relative text-sm bg-grayBG2 hover:bg-[#37A945] px-3 py-1 mt-2 w-fit text-center text-white rounded-full transition-all duration-300 cursor-pointer">
                      <p id="excelContainer">Choose</p>
                      <input
                        required
                        type="file"
                        onInputCapture={() => {
                          let imageInput =
                            document.getElementById("excelSheet");
                          imageInput.addEventListener("change", () => {
                            if (imageInput.files.length > 0) {
                              const fileName =
                                document.getElementById("excelSheet").files[0]
                                  .name;
                              document.getElementById(
                                "excelContainer"
                              ).innerHTML = fileName;
                            }
                          });
                        }}
                        id="excelSheet"
                        name="excelSheet"
                        className="h-full w-full opacity-0 absolute top-0 left-0"
                        accept="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,.xlsx,.xls,"
                      ></input>
                    </div>
                    <div
                      onClick={() => {
                        window.open(
                          process.env.REACT_APP_SERVER +
                            "/media/excels/Sample Products List.xlsx"
                        );
                      }}
                      className="relative text-sm bg-grayBG2 hover:bg-[#37A945] px-3 py-1 mt-2 w-fit text-center text-white rounded-full transition-all duration-300 cursor-pointer"
                    >
                      Download
                    </div>
                  </div>
                  <Link
                    to={`/dashboard/hot-products`}
                    className="flex items-center mt-2 gap-2"
                  >
                    <p className="text-[#37A945] font-normal underline">
                      View Hot Product List
                    </p>
                    <svg
                      width="11"
                      height="9"
                      viewBox="0 0 11 9"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        d="M5.68306 0.308058C5.92713 0.0639806 6.32286 0.0639806 6.56694 0.308058L10.3169 4.05806C10.4341 4.17527 10.5 4.33424 10.5 4.5C10.5 4.66576 10.4341 4.82473 10.3169 4.94194L6.56694 8.69194C6.32286 8.93602 5.92713 8.93602 5.68306 8.69194C5.43898 8.44787 5.43898 8.05214 5.68306 7.80806L8.36611 5.125L1.125 5.125C0.779822 5.125 0.5 4.84518 0.5 4.5C0.5 4.15482 0.779822 3.875 1.125 3.875L8.36611 3.875L5.68306 1.19194C5.43898 0.947864 5.43898 0.552136 5.68306 0.308058Z"
                        fill="#37A945"
                      />
                    </svg>
                  </Link>
                </div>
              </div>
            </div>
            <div id="editorContainer" className="w-full px-5">
              <div id="editor" style={{ zoom: "140%" }}>
                <textarea
                  id="edit"
                  name="edit"
                  className="opacity-0"
                ></textarea>
              </div>
            </div>
            <div className="w-full px-5 mt-3 flex items-center justify-end gap-4">
              <button className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300">
                Cancel
              </button>
              <button
                onClick={() => {
                  setLoading("");
                  let formData = new FormData();
                  if (document.getElementById("excelSheet").files.length <= 0) {
                    if (
                      document.getElementById("productName").value === "" ||
                      document.getElementById("category").value === "" ||
                      document.getElementById("modelNo").value === "" ||
                      document.getElementById("edit").value ===
                        "<!DOCTYPE html><html><head><title></title></head><body></body></html>"
                      // || document.getElementById("images").files.length === 0
                    ) {
                      setLoading("hidden");
                      alert("Please fill all the fields");
                    } else {
                      formData.append(
                        "productName",
                        document.getElementById("productName").value
                      );
                      formData.append(
                        "category",
                        document.getElementById("category").value
                      );
                      if (subCategory == "") {
                        formData.append("subCategory", null);
                      } else {
                        formData.append(
                          "subCategory",
                          document.getElementById("subCategory").value
                        );
                      }
                      formData.append(
                        "modelNo",
                        document.getElementById("modelNo").value
                      );
                      formData.append(
                        "description",
                        document.getElementById("edit").value
                      );
                      formData.append(
                        "isOnHome",
                        document.getElementById("isOnHome").checked
                      );

                      //   formData.append(
                      //     "images",
                      //     document.getElementById("images").files[0]
                      //   );
                      try {
                        formData.append(
                          "productPdf",
                          document.getElementById("pdf").files[0]
                        );
                      } catch (err) {}
                      formData.append(
                        "ytLink",
                        document.getElementById("ytLink").value
                      );
                      let images = files;
                      for (let i = 0; i < images.length; i++) {
                        formData.append("images", images[i].file);
                      }
                      console.log(formData);
                      axios({
                        url: process.env.REACT_APP_SERVER + "/api/addProduct/",
                        method: "POST",
                        headers: {
                          "Content-Type": "multipart/form-data",
                        },
                        data: formData,
                      })
                        .then((res) => {
                          setLoading("hidden");
                          window.location.reload();
                        })
                        .catch((err) => {
                          setLoading("hidden");
                          alert(err);
                        });
                    }
                  } else {
                    formData.append(
                      "productName",
                      document.getElementById("productName").value
                    );
                    formData.append(
                      "category",
                      document.getElementById("category").value
                    );
                    formData.append(
                      "modelNo",
                      document.getElementById("modelNo").value
                    );
                    formData.append(
                      "description",
                      document.getElementById("edit").value
                    );
                    formData.append(
                      "isOnHome",
                      document.getElementById("isOnHome").checked
                    );
                    // formData.append(
                    //   "images",
                    //   document.getElementById("images").files[0]
                    // );
                    formData.append(
                      "productPdf",
                      document.getElementById("pdf").files[0]
                    );
                    formData.append(
                      "excelSheet",
                      document.getElementById("excelSheet").files[0]
                    );
                    formData.append(
                      "ytLink",
                      document.getElementById("ytLink").value
                    );
                    let images = files;
                    for (let i = 0; i < images.length; i++) {
                      formData.append("images", images[i].file);
                    }
                    console.log(formData);
                    axios({
                      url: process.env.REACT_APP_SERVER + "/api/addProduct/",
                      method: "POST",
                      headers: {
                        "Content-Type": "multipart/form-data",
                      },
                      data: formData,
                    })
                      .then((res) => {
                        setLoading("hidden");
                        alert(res["data"]["msg"]);
                        window.location.reload();
                      })
                      .catch((err) => {
                        setLoading("hidden");
                        alert(err);
                      });
                  }
                }}
                className="bg-white hover:bg-[#37A945] text-kijeka-blue border-1 border-kijeka-blue hover:border-[#37A945] hover:text-white font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
              >
                Save
              </button>
            </div>
          </TabContent>
          <TabContent id="tab2" activeTab={activeTab}>
            <div className="w-full">
              <Link to={`/dashboard/all-products`}>
                <p className="px-5 md:hidden block mb-4 text-description font-semibold text-[#37A945] underline">
                  View All Uploaded Products
                </p>
              </Link>
              <div className="md:p-5 px-5 flex items-center flex-col md:flex-row gap-5">
                <div className="flex items-start flex-col md:flex-row w-full gap-5 md:w-[60%]">
                  <div className="w-full">
                    <div className="w-full">
                      <p className="font-medium">Name Of Category</p>
                      <input
                        type="text"
                        id="categoryName"
                        name="categoryName"
                        className="outline-none border border-gray-400 rounded-lg py-2 px-4 mt-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue md:w-64 w-full transition-all duration-300"
                        placeholder="Category Name"
                      />
                    </div>
                    <div className="flex items-center my-5 gap-3">
                      <input
                        aria-describedby="subCategoryCheckboxID"
                        id="isSubCategory"
                        name="isSubCategory"
                        type="checkbox"
                        className="bg-gray-50 border-gray-300 focus:ring-3 focus:ring-blue-300 h-4 w-4 rounded"
                        onClick={handleSubCategory}
                      />
                      <label
                        htmlFor="subCategoryCheckboxID"
                        className="font-normal"
                      >
                        Sub Category
                      </label>
                    </div>
                    <div className="w-full">
                      <p
                        className="font-medium text-gray-300"
                        id="subCategoryLabel"
                      >
                        Name Of Sub-Category
                      </p>
                      <input
                        type="text"
                        id="subCategoryName"
                        name="subCategoryName"
                        className="outline-none border border-gray-400 rounded-lg py-2 px-4 my-3 focus:ring-1 focus:ring-kijeka-blue focus:border-kijeka-blue md:w-64 w-full transition-all duration-300 cursor-not-allowed"
                        placeholder="Sub-Category Name"
                        disabled
                      />
                    </div>
                  </div>
                  <div id="editorContainerCategory" className="w-full">
                    <div id="editorCategory" style={{ zoom: "140%" }}>
                      <textarea
                        id="editCategory"
                        name="editCategory"
                      ></textarea>
                    </div>
                  </div>
                </div>
                <div className="md:w-[40%] w-full h-full">
                  <h1 className="text-kijeka-blue font-bold text-base">
                    Added Categories
                  </h1>
                  <div className="max-h-[300px] overflow-y-scroll no-scrollbar">
                    {category.map((category, index) => (
                      <div
                        className="flex items-center justify-between w-full bg-white px-4 py-3 rounded-lg shadow-md border border-[#EBEBEB] my-2"
                        key={index}
                      >
                        <div className="flex items-center gap-4 max-w-[65%]">
                          <p className="text-sm font-semibold text-kijeka-blue">
                            {index + 1}.
                          </p>
                          <p className="text-sm font-semibold text-kijeka-blue truncate">
                            {category}
                          </p>
                        </div>
                        <div className="flex items-center gap-4">
                          <svg
                            onClick={() => {
                              document.getElementById("categoryName").value =
                                category;
                              let formData = new FormData();
                              formData.append("category", category);
                              axios({
                                url:
                                  process.env.REACT_APP_SERVER +
                                  "/api/getCategoryDescription/",
                                method: "POST",
                                headers: {
                                  "Content-Type": "multipart/form-data",
                                },
                                data: formData,
                              })
                                .then((res) => {
                                  document.getElementById(
                                    "editCategory"
                                  ).value = res["data"]["data"];
                                  document
                                    .getElementById("editorCategory")
                                    .getElementsByTagName(
                                      "iframe"
                                    )[0].contentWindow.document.body.innerHTML =
                                    res["data"]["data"];
                                })
                                .catch((err) => {
                                  alert(err);
                                });
                            }}
                            width="20"
                            height="20"
                            viewBox="0 0 19 19"
                            fill="none"
                            xmlns="http://www.w3.org/2000/svg"
                            className="cursor-pointer"
                          >
                            <path
                              d="M8.45589 1.44043H5.18427C2.49364 1.44043 0.806641 3.3453 0.806641 6.04205V13.3168C0.806641 16.0136 2.48577 17.9184 5.18427 17.9184H12.9053C15.6046 17.9184 17.2838 16.0136 17.2838 13.3168V9.7923"
                              stroke="#004B95"
                              strokeWidth="1.5"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                            <path
                              fillRule="evenodd"
                              clipRule="evenodd"
                              d="M6.12469 8.55544L12.6636 2.01656C13.4782 1.20281 14.7986 1.20281 15.6132 2.01656L16.6781 3.08144C17.4927 3.89606 17.4927 5.21731 16.6781 6.03106L10.1077 12.6014C9.75157 12.9576 9.26857 13.1579 8.76457 13.1579H5.48682L5.56907 9.85044C5.58132 9.36394 5.77994 8.90019 6.12469 8.55544Z"
                              stroke="#004B95"
                              strokeWidth="1.5"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                            <path
                              d="M11.6694 3.02637L15.6647 7.02162"
                              stroke="#004B95"
                              strokeWidth="1.5"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            />
                          </svg>
                          <p className="bg-[#D9D9D9] px-2 py-1 text-gray-400 text-xs font-semibold rounded-full hover:bg-red-500 hover:text-white cursor-pointer transition-all duration-300">
                            Remove
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <div className="w-full px-5 mt-3 flex items-center gap-4">
                <button className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300">
                  Cancel
                </button>
                <button
                  onClick={() => {
                    setLoading("");
                    let formData = new FormData();
                    if (
                      document.getElementById("categoryName").value === "" ||
                      document.getElementById("editCategory").value ===
                        "<!DOCTYPE html><html><head><title></title></head><body></body></html>"
                    ) {
                      setLoading("hidden");
                      alert("Please fill all the fields");
                    } else {
                      formData.append(
                        "categoryName",
                        document.getElementById("categoryName").value
                      );
                      formData.append(
                        "isSubCategory",
                        document.getElementById("isSubCategory").checked
                      );
                      if (
                        document.getElementById("isSubCategory").checked ===
                        true
                      ) {
                        formData.append(
                          "subCategoryName",
                          document.getElementById("subCategoryName").value
                        );
                      }
                      formData.append(
                        "discription",
                        document.getElementById("editCategory").value
                      );
                      axios({
                        url: process.env.REACT_APP_SERVER + "/api/addCategory/",
                        method: "POST",
                        headers: {
                          "Content-Type": "multipart/form-data",
                        },
                        data: formData,
                      })
                        .then((res) => {
                          setLoading("hidden");
                          alert(res["data"]["msg"]);
                        })
                        .catch((err) => {
                          setLoading("hidden");
                          alert(err);
                        });
                    }
                  }}
                  className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300"
                >
                  Add
                </button>
              </div>
            </div>
          </TabContent>
        </div>
      </div>
    </div>
  );
};

