import React from "react";
import { FilePond, registerPlugin } from "react-filepond";
import "filepond/dist/filepond.min.css";
import FilePondPluginImageExifOrientation from "filepond-plugin-image-exif-orientation";
import FilePondPluginImagePreview from "filepond-plugin-image-preview";
import "filepond-plugin-image-preview/dist/filepond-plugin-image-preview.css";
import parse from "html-react-parser";

registerPlugin(FilePondPluginImageExifOrientation, FilePondPluginImagePreview);

function Review() {
	const [files, setFiles] = React.useState([]);
	React.useEffect(() => {
		document.title = "Kijeka | Review";
	});
	window.onload = () => {
		// document.getElementsByClassName("filepond--credits")[0].remove();
		document.getElementsByClassName("filepond--browser")[0].setAttribute("accept", "image/png, image/jpeg, image/gif");
	};
	return (
		<>
		{parse(`<style>.filepond--item {width: 100% !important;	max-height: 100% !important;min-height: 100% !important;</style>`)}
			<div className="sm:bg-[#EAEAEA] min-h-screen px-12">
				<div className="pl-7 pt-5  max-sm:pt-7 max-sm:pl-36 flex justify-start">
					<h1 className="text-sidebar max-sm:text-center flex max-sm:text-2xl text-xl font-bold">Review</h1>
				</div>

				<div className="sm:flex sm:bg-[#EAEAEA] overflow-x-hidden sm:justify-between">
					<div className="sm:border-2 sm:rounded-2xl sm:bg-white sm:shadow-inner sm:flex sm:m-5 w-[1000px] pb-5">
						<div className="flex items-starts justify-between my-2 w-full px-10">
							<div className="flex flex-col justify-start">
								<div className="w-96">
									<h2 className=" max-sm:mb-0 font-semibold mt-7 max-sm:mt-10 mb-2 text-subtitle">Name Of Client</h2>
									<input className="outline-none w-full mr-96 max-sm:mr-0 max-sm:w-72 px-7  h-10  border-2  rounded-lg text-sm my-2 block" type="text" placeholder="Name" />
								</div>
								<div className="w-96">
									<h2 className="font-semibold my-2 max-sm:mb-0 max-sm:mt-20 text-subtitle">Upload Profile Image</h2>
									<div className="mt-2 w-32">
										<FilePond files={files} allowReorder={true} styleLoadIndicatorPosition="center bottom" styleProgressIndicatorPosition="right bottom" styleButtonRemoveItemPosition="left bottom" styleButtonProcessItemPosition="right bottom" stylePanelLayout="compact circle" onupdatefiles={setFiles} labelIdle='Drag & Drop your files or <span className="filepond--label-action">Browse</span>' credits={null} />
									</div>
								</div>
							</div>
							<div className="flex max-sm:mt-32 max-sm:flex-col max-sm:justify-start flex-col">
								<h2 className="font-semibold max-sm:mb-0 mt-7 mb-2 text-subtitle">Write Content</h2>
								<textarea className="outline-none border-2 rounded-lg max-sm:mr-0 text-sm p-2 w-96 max-sm:w-72 pr-32 resize-none" type="text" rows="5" />

								<div className="flex justify-end items-center mt-10">
									<button className="bg-[#A6A6A64D] hover:bg-[#F21818] hover:text-white text-[#808080] font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300">Cancel</button>
									<div className="mx-3">
										<button className="bg-kijeka-blue hover:bg-[#37A945] text-white font-medium text-description px-8 py-2 rounded-lg cursor-pointer transition-all duration-300">Upload</button>
									</div>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		</>
	);
}

export default Review;
